window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_014"]={"n":"赵孟頫","dyn":"元","poems":[{"t":"岳鄂王墓","f":"七言律诗","c":["鄂王坟上草离离，秋日荒凉石兽危。","南渡君臣轻社稷，中原父老望旌旗。","英雄巳死嗟何及，天下中分遂不支。","莫向西湖歌此曲，水光山色不胜悲。"]},{"t":"天冠山题咏二十二首 其十 玉帘泉","f":"五言绝句","c":["飞泉如玉帘，直下数千尺。","新月横帘钩，遥遥挂空碧。"]},{"t":"东城","f":"七言绝句","c":["野店桃花红粉姿，陌头杨柳绿烟丝。","不因送客东城去，过却春光总不知。"]},{"t":"绝句","f":"七言绝句","c":["春寒恻恻掩重门，金鸭香残火尚温。","燕子不来花又落，一庭风雨自黄昏。"]},{"t":"次韵刚父即事绝句 其四","f":"七言绝句","c":["溪头月色白如沙，近水楼台一万家。","谁向夜深吹玉笛，伤心莫听《后庭花》。"]},{"t":"大都遇平江龙兴寺僧閒上座话唐綦毋潜宿龙兴寺诗因次其韵","f":"五言律诗","c":["闻说龙兴寺，多年未款扉。","风林发松籁，雨砌长苔衣。","殿古灯光定，房深磬韵微。","秋风动归兴，一锡向空飞。"]},{"t":"见章得一诗因次其韵二首 其一","f":"七言律诗","c":["水色清涟日色黄，梨花淡白柳花香。","即看时节催人事，更觉春愁恼客肠。","无酒难供陶令饮，从人皆笑郦生狂。","城南风暖游人少，自在晴丝百尺长。"]},{"t":"次韵王时观","f":"七言律诗","c":["相思吴越动经年，一见情深重惘然。","草木变衰人易老，江湖牢落雁难前。","秦山半出青天上，禹穴遥临古道边。","欲说旧游浑似梦，何时重上剡溪船？"]},{"t":"次韵信仲晚兴","f":"七言律诗","c":["萧萧残照晚当楼，寒叶疏云乱客愁。","岁月蹉跎星北指，乾坤浩荡水东流。","古来人物俱黄土，少日心情在一丘。","独立无言风满袖，青山相对共悠悠。"]},{"t":"次韵端父和鲜于伯几所寄诗","f":"七言律诗","c":["画舸西湖到处游，别来飞梦到杭州。","百年底用忧千岁，一日相思似几秋。","苦忆东南多胜事，空吟西北有高楼。","只今赖有刘公干，时写新诗解客愁。"]},{"t":"纪旧游","f":"七言律诗","c":["二月江南莺乱飞，百花满树柳依依。","落红无数迷歌扇，嫩绿多情妒舞衣。","金鸭焚香川上暝，画船挝鼓月中归。","如今寂寞东风里，把酒无言对夕晖。"]},{"t":"和姚子敬秋怀五首 其三","f":"七言律诗","c":["搔首风尘双短鬓，侧身天地一儒冠。","中原人物思王猛，江左功名愧谢安。","苜蓿秋高戎马健，江湖日短白鸥寒。","金尊渌酒无钱共，安得愁中却暂欢。"]},{"t":"鱼乐楼","f":"五言律诗","c":["楼下南来水，清泠百尺深。","菰蒲终夜响，杨柳半溪阴。","日月驱人世，江湖动客心。","向来歌舞宴，达晓看横参。"]},{"t":"闻捣衣","f":"七言律诗","c":["露下碧梧秋满天，砧声不断思绵绵。","北来风俗犹存古，南度衣冠不及前。","苜蓿总肥宛腰袅，琵琶曾泣汉婵娟。","人间俯仰成今古，何待他年始惘然。"]},{"t":"钱唐怀古","f":"七言律诗","c":["东南都会帝王州，三月莺花非旧游。","故国金人泣辞汉，当年玉马去朝周。","湖山靡靡今犹在，江水悠悠只自流。","千古兴亡尽如此，春风麦秀使人愁。"]},{"t":"溪上","f":"七言律诗","c":["溪上东风吹柳花，溪头春水净无沙。","白鸥自信无机事，玄鸟犹知有岁华。","锦缆牙樯非昨梦，凤笙龙管是谁家。","令人苦忆东陵子，拟问田园学种瓜。"]},{"t":"庆寿僧舍即事","f":"五言古诗","c":["白雨映青松，萧飒洒朱阁。","稍觉暑气销，微凉度疏箔。","客居秋寺古，心迹俱寂寞。","夕虫鸣阶砌，孤萤炯丛薄。","展转怀故乡，时闻风鸣铎。"]},{"t":"张詹事遂初亭","f":"五言古诗","c":["青山缭神京，佳气溢芳甸。","林亭去天咫，万状争自献。","年多嘉木合，春晚馀花殿。","雕阑留戏蝶，藻井语娇燕。","退食鸣玉珂，友于此终宴。","钟鼓乐清时，衣冠集群彦。","朝市尘得侵，图书味芳远。","纷华虽在眼，道胜安用战。","初心良已遂，雅志由此见。","何事江海人，山林未如愿。"]},{"t":"题商德符学士桃源春晓图","f":"七言古诗","c":["宿云初散青山湿，落红缤纷溪水急。","桃花源里得春多，洞口春烟摇绿萝。","绿萝摇烟挂绝壁，飞流淙下三千尺。","瑶草离离满涧阿，长松落落凌空碧。","鸡鸣犬吠自成村，居人至老不相识。","瀛洲仙客知仙路，点染丹青寄轻素。","何处有山如此图，移家欲向山中住。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其十九 七月","f":"五言古诗","c":["七月暑尚炽，长日弄机杼。","头蓬不暇梳，挥手汗如雨。","嘤嘤时鸟鸣，灼灼红榴吐。","何心娱耳目，往来忘伛偻。","织为机中素，老幼要纫补。","青灯照夜梭，蟋蟀窗外语。","辛勤亦何有，身体衣几缕。","嫁为田家妇，终岁服劳苦。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其八 八月","f":"五言古诗","c":["白露下百草，茎叶日纷委。","是时禾黍登，充积遍都鄙。","在郊既千庾，入邑复万轨。","人言田家乐，此乐谁可比。","租赋以输官，所馀足储峙。","不然风雪至，冻馁及妻子。","优游茅檐下，庶可以卒岁。","太平元有象，治世乃如此。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其四 四月","f":"五言古诗","c":["孟夏土加润，苗生无近远。","漫漫冒浅陂，芃芃被长阪。","嘉谷虽已值，恶草亦滋蔓。","君子与小人，并处必为患。","朝朝荷锄往，薅耨忘疲倦。","旦随鸟雀起，归与牛羊晚。","有妇念将饥，过午可无饭。","一饱不易得，念此独长叹。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其二十四 十二月","f":"五言古诗","c":["忽忽岁将尽，人事可稍休。","寒风吹桑林，日夕声飕飗。","墙南地不冻，垦掘为坑沟。","斫桑埋其中，明年芽早抽。","是月浴蚕种，自古相传流。","蚕出易脱壳，丝纩亦倍收。","及时不努力，知有来岁否。","手冻不足惜，冀免号寒忧。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其十七 五月","f":"五言古诗","c":["五月夏以半，谷莺先弄晨。","老蚕成雪茧，吐丝乱纷纭。","伐苇作薄曲，束缚齐榛榛。","黄者黄如金，白者白如银。","烂然满筐筥，爱此颜色新。","欣欣举家喜，稍慰经时勤。","有客过相问，笑声闻四邻。","论功何所归，再拜谢蚕神。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其二十一 九月","f":"五言古诗","c":["季秋霜露降，凛凛寒气生。","是月当授衣，有布织未成。","天寒催刀尺，机杼可无营。","教女学纺纑，举足疾且轻。","舍南与舍北，嘒嘒闻车声。","通都富豪家，华屋贮娉婷。","被服杂罗绮，五色相间明。","听说贫家女，恻然当动情。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其十二 十二月","f":"五言古诗","c":["一日不力作，一日食不足。","惨淡岁云莫，风雪入破屋。","老农气力衰，伛偻腰背曲。","索绹民事急，昼夜互相续。","饭牛欲牛肥，茭藁亦预蓄。","蹇驴虽劣弱，挽车致百斛。","农事极劳苦，岁岂恒稔熟。","能知稼穑艰，天下自蒙福。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其十三 正月","f":"五言古诗","c":["正月新献岁，最先理农器。","女工并时兴，蚕室临期治。","初阳力未胜，早春尚寒气。","窗户当奥密，勿使风雨至。","田畴耕耨动，敢不脩耒耜。","经冬牛力弱，相戒勤饭饲。","万事非预备，仓卒恐不易。","田家亦良苦，舍此复何计。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其二十三 十一月","f":"五言古诗","c":["冬至阳来复，草木潜滋萌。","君子重其然，吾道自此亨。","父母坐堂上，子孙列前荣。","再拜称上寿，所愿百福并。","人生属明时，四海方太平。","民无札瘥者，厚泽敷群情。","衣食苟给足，礼义自此生。","愿言兴学校，庶几教化成。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其二十二 十月","f":"五言古诗","c":["丰年禾黍登，农心稍逸乐。","小儿渐长大，终岁荷锄钁。","目不识一字，每念心作恶。","东邻方迎师，收拾令入学。","后月日南至，相贺因旧俗。","为女裁新衣，脩短巧量度。","龟手事塞向，庶禦北风虐。","人生真可叹，至老长力作。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其十一 十一月","f":"五言古诗","c":["农家值丰年，乐事日熙熙。","黑黍可酿酒，在牢羊豕肥。","东邻有一女，西邻有一儿。","儿年十五六，女大亦可笄。","财礼不求备，多少取随宜。","冬前与冬后，昏嫁利此时。","但愿子孙多，门户可扶持。","女当力蚕桑，男当力耘耔。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其十六 四月","f":"五言古诗","c":["四月夏气清，蚕大已属眠。","高首何昂昂，蛾眉复娟娟。","不忧桑叶少，遍野如绿烟。","相呼携筐去，迢递立远阡。","梯空伐条枚，叶上露未乾。","蚕饥当早归，秉心静以专。","饬躬脩妇事，僶勉当盛年。","救忙多女伴，笑语方喧然。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其七 七月","f":"五言古诗","c":["大火既西流，凉风日凄厉。","古人重稼穑，力田在匪懈。","郊行省农事，禾黍何旆旆。","碾以他山石，玉粒使人爱。","大祀须粢盛，一一稽古制。","是为五谷长，异彼稊与稗。","炊之香且美，可用享上帝。","岂惟足食人，一饱有所待。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其五 五月","f":"五言古诗","c":["仲夏苦雨乾，二麦先后熟。","南风吹陇亩，惠气散清淑。","是为农夫庆，所望实其腹。","沽酒醉比邻，语笑声满屋。","纷然收穫罢，高廪起相属。","有周成王业，后稷播百谷。","皇天贻来牟，长世自兹卜。","愿言仍岁稔，四海尽蒙福。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其一 正月","f":"五言古诗","c":["田家重元日，置酒会邻里。","小大易新衣，相戒未明起。","老翁年已迈，含笑弄孙子。","老妪惠且慈，白发被两耳。","杯盘且罗列，饮食致甘旨。","相呼团栾坐，聊慰衰莫齿。","田硗藉人力，粪壤要锄理。","新岁不敢闲，农事自兹始。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其十五 三月","f":"曲","c":["三月蚕始生，纤细如牛毛。","婉娈闺中女，素手握金刀。","切叶以饲之，拥?散周遭。","庭树鸣黄鸟，发声和且娇。","蚕饥当采桑，何暇事游遨。","田时人力少，丈夫方种苗。","相将挽长条，盈筐不终朝。","数口望无寒，敢辞终岁劳。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其六 六月","f":"五言古诗","c":["当昼耘水田，农夫亦良苦。","赤日背欲裂，白汗洒如雨。","匍匐行水中，泥淖及腰膂。","新苗抽利剑，割肤何痛楚。","夫耘妇当馌，奔走及亭午。","无时暂休息，不得避炎暑。","谁怜万民食，粒粒非易取。","愿陈知稼穑，《无逸》传自古。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其十八 六月","f":"五言古诗","c":["釜下烧桑柴，取茧投釜中。","纤纤女儿手，抽丝疾如风。","田家五六月，绿树阴相蒙。","但闻缲车响，远接村西东。","旬日可经绢，弗忧杼轴空。","妇人能蚕桑，家道当不穷。","更望时雨足，二麦亦稍丰。","沽酒田家饮，醉倒妪与翁。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其二 二月","f":"五言古诗","c":["东风吹原野，地冻亦已销。","早觉农事动，荷锄过相招。","迟迟朝日上，炊烟出林梢。","土膏脉既起，良耜利若刀。","高低遍翻垦，宿草不待烧。","幼妇颇能家，井臼常自操。","散灰缘旧俗，门径环周遭。","所冀岁有成，殷勤在今朝。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其三 三月","f":"五言古诗","c":["良农知土性，肥瘠有不同。","时至万物生，芽蘖由地中。","秉耒向畎亩，忽遍西与东。","举家往于田，劳瘁在尔农。","春雨及时降，被野何濛濛。","乘兹各布种，庶望西成功。","培根利秋实，仰天望年丰。","但使阴阳和，自然仓廪充。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其二十 八月","f":"五言古诗","c":["池水何洋洋，沤麻水中央。","数日麻可取，引过两手长。","织绢能几时，织布巳复忙。","依依小儿女，岁晚叹无裳。","布襦不掩胫，念之热中肠。","朝缉满一篮，莫缉满一筐。","行看机中布，计日渐可量。","我衣苟巳成，不忧天早霜。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其十 十月","f":"五言古诗","c":["孟冬农事毕，谷粟既已藏。","弥望四野空，藁秸亦在场。","朝廷政方理，庶事和阴阳。","所以频岁登，不忧旱与蝗。","置酒燕乡里，尊老列上行。","肴羞不厌多，炰羔复烹羊。","纵饮穷日夕，为乐殊未央。","祷天祝圣人，万年长寿昌。"]},{"t":"题耕织图二十四首奉懿旨撰 织 其十四 二月","f":"五言古诗","c":["仲春冻初解，阳气方满盈。","旭日照原野，万物皆欣荣。","是时可种桑，插地易抽萌。","列树遍阡陌，东西各纵横。","岂惟篱落间，采叶惮远行。","大哉皇元化，四海无交兵。","种桑日已广，弥望绿云平。","匪惟锦绮谋，祗以厚民生。"]},{"t":"题耕织图二十四首奉懿旨撰 耕 其九 九月","f":"曲","c":["大家饶米面，何啻百室盈。","纵复人力多，舂磨常不停。","激水转大轮，硙碾亦易成。","古人有机智，用之可厚生。","朝出连百车，莫入还满庭。","勾稽数多少寡，必假布算精。","小人好争利，昼夜心营营。","君子贵知足，知足万虑轻。"]},{"t":"人月圆","f":"曲","c":["一枝仙桂香生玉，消得唤卿卿。","缓歌金缕，轻敲象板，倾国倾城。","几时不见，红裙翠袖，多少闲情。","想应如旧，春山淡淡，秋水盈盈。"]},{"t":"万年欢 中吕宫元日朝会","f":"曲","c":["天上春来。","正阳和布泽，斗柄初回。","一朵祥云捧日，万象生辉。","帝德照光四表，玉帛尽、梯航来会。","彤庭敞，花覆千官，紫霄鹓鹭徘徊。","仁风遍满九垓。","望霓旌缓引，宝扇徐开。","喜动龙颜，和气蔼然交泰。","九奏箫韶舜乐，兽尊举、麒麟香叆。","从今数，亿万斯年，圣主福如天大。"]},{"t":"万年欢 应制","f":"曲","c":["阊阖初开。","正苍苍曙色，天上春回。","绛帻鸡人时报，禁漏频催。","九奏钧天帝乐，御香惹、千官环佩。","鸣鞘静，嵩岳三呼，万岁声震如雷。","殊方异域尽来。","满彤庭贡珍，皇化无外。","日绕龙颜，云近绛阙蓬莱。","四海欢欣鼓舞，圣德过、唐虞三代。","年年宴，王母瑶池，紫霞长进琼杯。"]},{"t":"少年游","f":"曲","c":["弄晴微雨细丝丝。","山色淡无姿。","柳絮飞残，荼蘼开罢，青杏已团枝。","栏干倚遍人何处，愁听语黄鹂。","宝瑟尘生，翠销香减，天远雁书迟。"]},{"t":"太常引","f":"曲","c":["水风吹树晚萧萧。","散发醉吹箫。","尘事苦如毛。","要洗耳、时听舜韶。","旧游何处，琼山银海，宫殿郁岧峣。","谁与共游遨。","尚记得、仙人子乔。"]},{"t":"月中仙 应制","f":"曲","c":["春满皇州。","见祥烟拥日，初照龙楼。","宫花苑柳，映仙仗云移，金鼎香浮。","宝光生玉斧，听鸣凤、箫韶乐奏。","德与和气游。","天生圣人，千载稀有。","祥瑞电绕虹流。","有云成五色，芝生三秀。","四海太平，致民物雍熙，朝野歌讴。","千官齐拜舞，玉杯进、长生春酒。","愿皇庆万年，天子与天齐寿。"]},{"t":"木兰花慢 和李筼房韵","f":"曲","c":["爱青山绕县，更山下、水萦回。","有二老风流，故家乔木，旧日亭台。","梅花乱零春雪，喜相逢、置酒藉苍苔。","拚却眼迷朱碧，惭无笔泻琼瑰。","徘徊。","俯仰兴怀。","尘世事，本无涯。","偶乘兴来游，临流一笑，洗尽征埃。","归来算未几日，又青回、柳叶燕重来。","但愿朱颜长在，任他花落花开。"]},{"t":"木兰花慢 和桂山庆新居韵","f":"曲","c":["爱风流二陆，曾共住、屋三间。","算京洛缁尘，平原车骑、争似身闲。","一区未输场子，更友于、室迩足清欢。","庭下新松楚楚，篱边细菊班班。","白头相对且团圞。","杯酒借朱颜。","任醉后长歌，笑时开口，乐最人寰。","功名十年一梦，记风裘雪帽度桑乾。","幸喜归来健在，放怀绿水青山。"]},{"t":"水龙吟 次韵程仪父荷花","f":"曲","c":["凌波罗袜生尘，翠旌孔盖凝朝露。","仙风道骨，生香真色，人间谁妒。","伫立无言，长疑遗世，飘然轻举。","笑阳台梦里，朝朝暮暮，为云又还为雨。","狼藉红衣脱尽，羡芳魂不埋黄土。","涉江径去，采菱拾翠，携俦啸侣。","宝玦空悬，明珰偷解，相逢洛浦。","正临风歌断，一双翡翠，背人飞去。"]},{"t":"水龙吟 题箫史图","f":"曲","c":["倚天百尺高台，雕檐画栋撑云表。","夜静无尘，秋魂万里，月明如扫。","谁凭栏干，玉箫声起，乘鸾人到。","信情缘有自，何须更说，姮娥空老。","我将醉眼摩挲，是谁人丹青图巧。","为惜秦姬，堪怜箫史，写成烦恼。","万古风流，传芳至此，交人倾倒。","问双星有会，一年一度，那知清晓。"]},{"t":"水调歌头","f":"曲","c":["行止岂人力，万事总由天。","燕南越北鞍马，奔走度流年。","今日芙蓉洲上，洗尽平生尘土，银汉溢清寒。","却忆旧游处，回首万山间。","客无哗，君莫舞，我欲眠。","一杯到手先醉，明月为谁圆。","莫惜频开笑口，只恐便成陈迹，乐事几人全。","但愿身无恙，常对月婵娟。"]},{"t":"长寿仙 道宫皇庆三年三月三日圣节大宴","f":"曲","c":["瑞日当天。","对绛阙蓬莱，非雾非烟。","翠光覆禁苑。","正淑景芳妍。","彩仗和风细转。","御香飘满黄金殿。","喜万国会朝，千官拜舞，亿兆同欢。","福祉如山如川。","应玉渚流虹，璇枢飞电。","八音奏舜韶，庆玉烛调元。","岁岁龙舆凤辇。","九重春醉蟠桃宴。","天下太平，祝吾皇，寿与天地齐年。"]},{"t":"江城子 赋水仙","f":"曲","c":["冰肌绰约态天然。","淡无言。","带蹁跹。","遮莫人间，凡卉避清妍。","承露玉杯餐沆瀣，真合唤，水中仙。","幽香冉冉暮江边。","佩空捐。","恨谁传。","遥夜清霜，翠袖怯春寒。","罗袜凌波归去晚，风袅袅，月娟娟。"]},{"t":"巫山一段云 上升峰","f":"曲","c":["云里高唐观，江边楚客舟。","上升峰月照妆楼。","离思两悠悠。","云雨千重阻，长江一片秋。","歌声频唱引离愁。","光景恨如流。"]},{"t":"巫山一段云 净坛峰","f":"曲","c":["叠嶂千重碧，长江一带清。","瑶坛霞冷月胧明。","欹枕若为情。","云过船窗晓，星移宿雾晴。","古今离恨拨难平。","惆怅峡猿声。"]},{"t":"巫山一段云 松鹤峰","f":"曲","c":["枫鹤堆岚霭，阳台枕水湄。","风清月冷好花时。","惆怅阻佳期。","别梦游蝴蝶，离歌怨竹枝。","悠悠往事不胜悲。","春恨入双眉。"]},{"t":"巫山一段云 栖凤峰","f":"曲","c":["芍药虚投赠，丁香漫结愁。","凤栖鸾去两悠悠。","新恨怯逢秋。","山色惊心碧，江声入梦流。","何时弦管簇归舟。","兰棹泊沙头。"]},{"t":"巫山一段云 起云峰","f":"曲","c":["袅娜江边柳，飘摇岭上云。","卸帆回棹楚江滨。","归信夜来闻。","欲拂珊瑚枕，先董翡翠裙。","江头含笑去迎君。","鸾凤尽成群。"]},{"t":"巫山一段云 望泉峰","f":"曲","c":["晓色飘红叶，平沙枕碧流。","泉声云影弄新秋。","触处是离愁。","脸泪横波漫，眉攒片月收。","佳人欲笑卒难休。","半整玉搔头。"]},{"t":"巫山一段云 望霞峰","f":"曲","c":["碧水鸳鸯浴，平沙豆蔻红。","云霞峰翠一重重。","帆卸落花风。","淡薄云笼月，霏微雨洒篷。","孤舟晚泊浪声中。","无处问音容。"]},{"t":"巫山一段云 朝云峰","f":"曲","c":["绝顶朝云散，寒江暮雨频。","楚王宫殿已成尘。","过客转伤神。","月是巫娥伴，花为宋玉邻。","一听歌调一含颦。","幽怨竹枝春。"]},{"t":"巫山一段云 登龙峰","f":"曲","c":["片月生危岫，残霞拂翠桐。","登龙峰下楚王宫。","千古感遗踪。","柳色眉边绿，花明脸上红。","欲寻灵迹阻江风。","离思杳无穷。"]},{"t":"巫山一段云 集仙峰","f":"曲","c":["雨过苹汀远，云深水国遥。","渡头齐举木兰桡。","纤细楚宫腰。","映水匀红脸，偎花整翠翅。","行人倚棹正无聊。","一望一魂销。"]},{"t":"巫山一段云 翠屏峰","f":"曲","c":["碧水澄青黛，危峰耸翠屏。","竹枝歌怨月三更。","别是断肠声。","烟外黄牛峡，云中白帝城。","扁舟清夜泊苹汀。","倚棹不胜情。"]},{"t":"巫山一段云 聚鹤峰","f":"曲","c":["鹤信三山远，罗裙片水深。","高唐春梦杳难寻。","惆怅到如今。","十二峰前月，三千里外心。","红笺锦字信沉沉。","肠断旧香衾。"]},{"t":"苏武慢","f":"曲","c":["北陇耕云，南溪钓月，此是野人生计。","山鸟能歌，山花解笑，无限乾坤生意。","看画归来，挑簦闲眺，风景又还光霁。","笑人生、奔波如狂，万事不如沉醉。","细看来、聚蚁功名，战蜗事业，毕竟又成何济。","有分山林，无心钟鼎，誓与渔樵深契。","石上酒醒，山间茶熟，别有水云风味。","顺吾生、素位而行，造化任他儿戏。"]},{"t":"南乡子","f":"曲","c":["云拥髻鬟愁。","好在张家燕子楼。","稀翠疏红春欲透，温柔。","多少闲情不自由。","歌罢锦缠头。","山下晴波左右流。","曲里吴音娇未改，障羞。","一朵芙蓉满扇秋。"]},{"t":"点绛唇","f":"曲","c":["昏晓相催，百年窗暗窗明里。","人生能几。","赢得貂裘敝。","富贵浮云，休恋青绫被。","归欤未。","放怀烟水。","不受风尘眯。"]},{"t":"浣溪沙","f":"七言古诗","c":["满捧金卮低唱词。","尊前再拜索新诗。","老夫惭愧鬓成丝。","罗袖染将修竹翠，粉香吹上小梅枝。","相逢不似少年时。"]},{"t":"浪淘沙令","f":"曲","c":["今古几齐州。","华屋山丘。","杖藜徐步立芳洲。","无主桃花开又落，空使人愁。","波上往来舟。","万事悠悠。","春风曾见昔人游。","只有石桥桥下水，依旧东流。"]},{"t":"渔父词二首 其二","f":"曲","c":["侬住东吴震泽州。","烟波日日钓鱼舟。","山似翠，酒如油。","醉眼看山百自由。"]},{"t":"渔父词二首 其一","f":"曲","c":["渺渺烟波一叶舟。","西风落木五湖秋。","盟鸥鹭，傲王侯。","管甚鲈鱼不上钩。"]},{"t":"虞美人","f":"曲","c":["池塘处处生春草。","芳思纷缭绕。","醉中时作短歌行。","无奈夕阳、偏旁小窗明。","故园荒径迷行迹。","只有山仍碧。","及今作乐送春归。","莫待春归、去后始知非。"]},{"t":"虞美人 浙江舟中作","f":"曲","c":["潮生潮落何时了。","断送行人老。","消沉万古意无穷。","尽在长空、淡淡鸟飞中。","海门几点青山小。","望极烟波渺。","何当驾我以长风。","便欲乘桴、浮到日华东。"]},{"t":"蝶恋花","f":"曲","c":["侬是江南游冶子。","鸟帽青鞋，行乐东风里。","落尽杨花春满地。","萋萋芳草愁千里。","扶上兰舟人欲醉。","日暮青山，相映双蛾翠。","万顷湖光歌扇底。","一声催下相思泪。"]},{"t":"题孤山放鹤图 其一","f":"曲","c":["西湖清且涟漪，扁舟时荡晴晖。","处处青山独往，翩翩白鹤迎归。"]},{"t":"玄洲十咏寄张贞居 其一 菌山","f":"五言绝句","c":["结苑依菌山，焚香候芝盖。","真灵幸悯我，冠佩时来会。"]},{"t":"玄洲十咏寄张贞居 其三 霞架海","f":"五言绝句","c":["众水会一壑，天近发霞光。","晨兴新沐竟，晞发向朝阳。"]},{"t":"玄洲十咏寄张贞居 其五 鹤台","f":"五言绝句","c":["上有白鹤翔，下有幽人居。","幽人道当成，白鹤来不虚。"]},{"t":"玄洲十咏寄张贞居 其四 桐花源","f":"五言绝句","c":["伊谁植斯桐，萋萋满幽谷。","鸣凤久不闻，何当一来宿。"]},{"t":"玄洲十咏寄张贞居 其六 玄洲精舍","f":"五言绝句","c":["子有鸾鹤想，甘同麋鹿游。","悬榻应待我，分我半玄洲。"]},{"t":"玄洲十咏寄张贞居 其七 紫轩","f":"五言绝句","c":["林君巳仙去，紫轩名尚存。","丹光时或现，药鼎夜常温。"]},{"t":"玄洲十咏寄张贞居 其八 火浣坛","f":"五言绝句","c":["真阳以解形，四大何足靳。","指穷於为薪，火传不知尽。"]},{"t":"玄洲十咏寄张贞居 其十 隐居松","f":"五言绝句","c":["真人昔住世，所至树以松。","当知千岁下，遗子以清风。"]},{"t":"玄洲十咏寄张贞居 其九 玉像龛","f":"五言绝句","c":["我有紫虚像，白玉雕琢成。","贡之华阳天，万年期降灵。"]},{"t":"人日立春","f":"七言律诗","c":["今年人日与春并，人得春来喜气迎。","宫柳风微金缕重，御沟冰泮玉鳞生。","阴消已觉馀寒散，阳长争看晓日明。","霜鬓綵幡浑不称，强题新句慰羁情。"]},{"t":"后庭花破子","f":"曲","c":["清溪一叶舟。","芙蓉两岸秋。","采菱谁家女，歌声起暮鸥。","乱云愁。","满头风雨，戴荷叶、归去休。"]},{"t":"有所思","f":"五言古诗","c":["思与君别来，几见芙蓉花。","盈盈隔秋水，若在天一涯。","欲涉不得去，茫茫足烟雾。","汀洲多芳草，何心采蘅杜。","青鸟翱云间，锦书何时还。","君心虽匪石，秪恐凋朱颜。","朱颜不可仗，那能不惆怅。","何如双翡翠，飞去兰苕上。"]},{"t":"和子俊感秋五首 其二","f":"五言古诗","c":["明月照北林，翩翩栖鸟翻。","虚室当静夜，幸绝人事喧。","念子巳独寐，无人相与言。","吾生性坦率，与世无竞奔。","空怀丘壑志，耿耿固长存。","何由持此意，往与严郑论。"]},{"t":"和子俊感秋五首 其五","f":"五言古诗","c":["白露泫然坠，草木日以凋。","閒居无尘杂，日薄风翛翛。","登高写我心，葵扇欲罢摇。","感时俯逝水，回睇仰层霄。","松乔在何许，高蹈不可招。","愿言从之游，怀古一何遥。"]},{"t":"岁莫和刚父杂诗四首 其三","f":"五言律诗","c":["惊飙吹白日，流光忽蹉跎。","登山采众芳，荆蓁一何多。","迷途幸未远，回车且委蛇。","黄鹄志四海，雀鴳将如何。"]},{"t":"岁莫和刚父杂诗四首 其四","f":"五言古诗","c":["肥马黄金鞍，轻裘华且鲜。","朅来从横驰，意气何翩翩。","朝为人所慕，夕巳为世怜。","此道固应尔，祸福非虚言。","生当称善人，死当谥为贤。","勿羡夸毗子，狂驰终百年。"]},{"t":"东郊","f":"五言古诗","c":["晨兴理孤榜，薄言东郊游。","清风吹我衣，入袂寒飕飕。","幽花媚时节，弱蒋依寒流。","山开碧云敛，日出白烟收。","旷望得所怀，欣然消我忧。","中流望城郭，葱葱佳气稠。","人生亦已繁，惠养要须周。","约身不愿馀，尚恐乏所求。","且当置勿念，乘化终归休。"]},{"t":"寄题右之此静轩","f":"五言古诗","c":["卜居无喧寂，尚论心所宗。","山林苟不静，亦与朝市同。","闻君南窗下，寄傲乐无穷。","曲肱有馀趣，战胜纷华中。","好风从何来，吹子庭前松。","清琴时一弹，浊酒尊不空。","颇恨道里赊，不得往相从。","人事矧好乖，我心何时降。"]},{"t":"赵村道中 其一","f":"五言古诗","c":["朝出南郭门，遥指西山阴。","马蹄与石斗，宛转愁我心。","溪谷莽回互，寒风振穹林。","黄叶洒我衣，岩泉走哀音。","凄凄霜露降，穷思浩难任。","人生亦何为，百年成古今。","华堂昔燕处，零落归丘岑。","况复不得保，悲来泪沾襟。"]},{"t":"奉詶戴帅初架阁见赠二首 其一","f":"五言古诗","c":["仙人海上来，遗我珊瑚钩。","晶光夺凡目，奇采耀九州。","自吾得此宝，昼玩夜不休。","生世勿恨晚，及与斯人俦。","惜哉无琼玖，可以结绸缪。","世德日下衰，古风向谁求。","蛾眉亦何有，空受众女仇。","适俗固所愿，违己良足忧。","感子赠言意，再拜涕泗流。","安得骑骐驎，从子以远游。"]},{"t":"桐庐道中","f":"五言古诗","c":["历历山水郡，行行襟抱清。","两崖束沧江，扁舟此宵征。","卧闻滩声壮，起见渚烟横。","西风林木净，落日沙水明。","高旻众星出，东岭素月生。","舟子棹歌发，含词感人情。","人情苦不远，东山有遗声。","岂不怀燕居，简书趣期程。","优游恐不免，驱驰竟何成。","我生悠悠者，何日遂归耕。"]},{"t":"罪出","f":"五言古诗","c":["在山为远志，出山为小草。","古语巳云然，见事苦不早。","平生独往愿，丘壑寄怀抱。","图书时自娱，野性期自保。","谁令堕尘网，宛转受缠绕。","昔为水上鸥，今如笼中鸟。","哀鸣谁复顾，毛羽日摧槁。","向非亲友赠，蔬食常不饱。","病妻抱弱子，远去万里道。","骨肉生别离，丘垄谁为扫。","愁深无一语，目断南云杳。","恸哭悲风来，如何诉穹昊。"]},{"t":"祷雨龙洞山","f":"五言古诗","c":["苍山如犬牙，细路入深谷。","绝壁千馀仞，上有凌云木。","阴崖不受日，洞穴自成屋。","萧森人迹少，荟蔚兽攸伏。","云林互隐映，涧道相回复。","翔禽薄穹霄，鸣鸟响岩曲。","临桥濯清飔，汲井漱寒玉。","神物此渊潜，愆阳有祈祝。","风漓惭善教，吏懦耻厚禄。","暂怀尘外想，独往疑有梏。","过幽难久居，济胜乏高躅。","策马寻故蹊，归樵相追逐。"]},{"t":"题归去来图","f":"五言古诗","c":["生世各有时，出处非偶然。","渊明赋归来，佳处未易言。","后人多慕之，效颦惑蚩妍。","终然不能去，俛仰尘埃间。","斯人真有道，名与日月悬。","青松卓然操，黄华霜中鲜。","弃官亦易耳，忍穷北窗眠。","抚卷三叹息，世久无此贤。"]},{"t":"次韵周公谨见赠","f":"五言古诗","c":["池鱼思故渊，槛兽念旧薮。","官曹困窘束，卯入常尽酉。","简书督期会，何用传不朽。","十年从世故，尘土满衣袖。","归来忽相见，忘此离别久。","缅怀德翁隐，坐羡沮溺耦。","新诗使我和，矉里忘己丑。","平生知我者，颇亦似公否。","山林期晚岁，鸡黍共尊酒。","却笑桓公言，凄然汉南柳。"]},{"t":"哀鲜于伯几","f":"五言古诗","c":["生别有再逢，死别终古隔。","君死巳五年，追痛犹一日。","我生大江南，君长淮水北。","忆昨闻令名，官舍始相识。","我方二十馀，君发黑如漆。","契合无间言，一见同宿昔。","春游每拿舟，夜坐常促席。","气豪声若钟，意愤髯屡戟。","谈谐杂叫啸，议论造精覈。","巍煌商鼎制，驵骏汉马式。","奇文既同赏，疑义或共析。","锦囊装玉轴，妙绝晋唐迹。","粲然极炫曜，观者咸辟易。","非君有精鉴，畴能萃奇物。","最后得玉钩，雕琢螭盘屈。","握手传玩馀，欢喜见颜色。","刻意学古书，池水欲尽黑。","书记往来间，彼此各有得。","我时学钟法，写君先墓石。","江南君所乐，地气苦下湿。","安知从事衫，竟卒奉常职。","至今屏障间，不忍睹遗墨。","凄凉方井路，松竹荫真宅。","乾坤清气少，人物世罕觌。","绯袍俨画像，对之泪沾臆。","宇宙一何悠，悲酸岂终极。"]},{"t":"新秋","f":"五言古诗","c":["夜久不能寐，坐来秋意浓。","露凉催蟋蟀，月白澹芙蓉。","渐觉綀衣薄，欲将纨扇慵。"]},{"t":"游幻往庵","f":"五言古诗","c":["雨后溪水溢，黄流行地中。","轻舟何迅迈，沿波兼顺风。","碧芦干始长，柔桑叶巳空。","瞬息抵山曲，窈窕微径通。","青林夹道周，流泉响幽丛。","多惭众衲子，前路相迎逢。","禅居新结构，斧斤未辍工。","双阁出尘嚣，六窗自玲珑。","久矣厌城市，飘如脱樊笼。","妙香清鼻观，新莺惊耳聋。","汲水插山花，开牖纳风松。","经声出廊庑，寂然闻鼓钟。","蔬食欣一饱，亦与膏粱同。","缅怀老尊宿，燕坐毗卢峰。","尘缘苦未断，无由往相从。","一宿返归棹，回望但青葱。"]},{"t":"清河道中","f":"五言律诗","c":["扬舲清河流，开篷素秋晓。","斓斑被厓花，委蛇顺流藻。","天清去雁高，野阔行人小。","故园归有期，客愁净如扫。"]},{"t":"七月六日承贞居先生远寄周钟铣间有女象凫之形则考工记所谓凫氏为钟者也击之与夷则合而是日又适立秋古物之来岂偶然哉辄成小诗拜贶之辱","f":"五言古诗","c":["故人赏我趣，遗我凫氏钟。","制与周礼合，试叩声舂容。","是日新秋节，夷则还为宫。","悬之西楣下，浮磬俨在东。","金石互相应，间以丝与桐。","八音虽未备，古乐将无同。","鼎尊铎觯卣，罗列见古风。","揖让於其间，令我怀周公。","作诗报嘉贶，庶以开群聋。"]},{"t":"题钱舜举着色梨花","f":"曲","c":["东风吹日花冥冥，繁枝压雪凌风尘。","素罗衣裳照青春，眼中若有梨园人。","攀条弄芳畏日夕，只今纸上空颜色。","颜色好，愁转多，与君沽酒花前歌。"]},{"t":"题西溪图赠鲜于伯几","f":"七言古诗","c":["山林忽然在我眼，揽袂欲游嗟巳远。","长松谡谡含苍烟，平川茫茫际曾巘。","大梁繁华天下稀，走马斗鸡夜忘归。","君独胡为甘寂寞，坐对山水娱清晖。","西溪先生奇崛士，正可着之岩石里。","数间茅屋破不脩，中有神光发奇字。","绿蘋齐叶白芷生，送君江南空复情。","相思万里不可见，时对此图双眼明。"]},{"t":"戏题出洗马","f":"七言律诗","c":["齧膝覂驾谁能御，驽蹇纷纷何足顾。","青丝络首锦障泥，鞭箠空劳怨长路。","明窗戏写乘黄姿，洗刷归来气如怒。","不须对此苦叹嗟，男儿自昔多徒步。"]},{"t":"送孟仲则游荆湖兼往襄汉","f":"七言古诗","c":["行路方难子何往，潇湘洞庭天一方。","长江风来浪如雪，荆门木落天雨霜。","千金养客不复见，万里访旧庸何伤。","子才有用未得试，牛刀爱惜藏锋铓。","似闻远游未渠央，更欲揽辔趍襄阳。","昔年战斗且休息，白骨巳瘗愁云黄。","伏龙凤雏在何处，鹿门山色还苍苍。","登高吊古一长啸，万事惨淡悲中肠。","人生聚散安可常，为君起舞君举觞。","明朝帆影拂浮玉，寄言客居思故乡。"]},{"t":"烈妇行","f":"曲","c":["客车何焞焞，夫挽妇为推。","问君将安去，言往枣阳戍。","官事有程宿车下，夜半可怜逢猛虎。","夫命悬虎口，妇怒发指天。","十步之内血相溅，夫难再得虎可前。","宁与夫死，毋与虎生。","呼儿取刃力与争，虎死夫活心始平。","男儿节义有如许，万岁千秋可以事明主，冯妇卞庄安足数。","呜呼猛虎逢尚可，宁成宁成奈何汝。"]},{"t":"送高仁卿还湖州","f":"七言古诗","c":["昔年东吴望幽燕，长路北走如登天。","捉来官府竟何补，还望故乡心惘然。","江南冬暖花乱发，朔方苦寒气又偏。","木皮三寸冰六尺，面颊欲裂冻折弦。","卢沟强弩射不过，骑马径度不用船。","宦游远客非所习，狐貉不具绨袍穿。","京师宜富不宜薄，青衫骏马争腾骞。","南邻吹笙厌粱肉，北里鼓瑟罗姝妍。","凄凉朝士有何意，瘦童羸骑鸡鸣前。","太仓粟陈未易籴，中都俸薄难裹缠。","尔来方士颇向用，读书不若烧丹铅。","故人闻之应见笑，如此不归殊可怜。","长林丰草我所爱，羁靮未脱无由缘。","高侯远来肯顾我，裹茗抱被来同眠。","青灯耿耿照土屋，白酒薄薄无荤膻。","破愁为笑出软语，寄书妻孥无一钱。","江湖浩渺足春水，凫雁灭没横秋烟。","何当乞身归故里，图书堆里消残年。"]},{"t":"谢鲜于伯几惠震馀琴云是许旌阳手植桐所斲","f":"七言古诗","c":["仙人巳归白云中，空馀手植青枝桐。","根柯盘郁如蛟龙，一朝辟历驱雷公，烈火半爇随狂风。","箕子之裔多髯翁，才气迈俗惊愚蒙。","抱持来归寻国工，斲为二琴含商宫。","我来自北欣相逢，持一赠我为我容。","自吾得此不敢寐，终夜起坐弹孤鸿。","下弦清泠上黄钟，转弦更张涕满胸。","黄虞巳远将无同，恨君不识牙与钟。","恨我不识瞽与矇，《周南》《大雅》当谁从。"]},{"t":"赠相者","f":"七言古诗","c":["吾闻伯乐善相马，一顾千金长高价。","何人倜傥买权奇，满眼驽骀居枥下。","张君年少目有神，走半江湖多阅人。","我生瘦愞乏骏骨，浪许腾骧防失真。","连朝春雨今始晴，花枝照眼生春情。","楼前山色横翠霭，湖上柳黄飞乱莺。","便须沽酒与君饮，醉倒花前犹满引。","懒从唐举问流年，欲向德翁谋小隐。"]},{"t":"秋夜曲 其一","f":"七言古诗","c":["雨声滴夜清漏长，朱帘金幕浮新凉。","闺中美人动裁剪，故罗衣袂生秋香。","东邻剥枣西邻穫，旅馆无人念飘泊。","馀不潦尽涵清辉，芙蓉压堤怨不归。","墙根草绿阴蛾飞。"]},{"t":"秋夜曲 其二","f":"七言古诗","c":["蒲萄架空堕殷玉，遥夜露寒生体粟。","暗蛩栖草鸣不平，无丝络纬空劳促。","梦魂苦短道苦长，万山深处非吾乡。","玉虫摇缸萤入屋，去雁来鱼应可卜。","醒眼荧荧愁万斛。"]},{"t":"孔道辅击蛇笏","f":"七言古诗","c":["以笏击蛇有孔公，义与段公击贼同。","事之钜细虽有异，正气愤激生于中。","伟哉孔公圣人裔，岂听妖邪乱民志。","即今槐木一尺强，气象凛凛含风霜。","子孙守之慎宝藏，绝胜象牙堆满床。"]},{"t":"燕脂骏图歌","f":"曲","c":["骐驎腰袅世常有，伯乐不生淹栈豆。","歘见此图神自王，权奇磊落龙为友。","隅目晶荧生紫光，锦毛错落蒙清霜。","霜蹄蹙踏寒玉响，雾鬣振动秋风凉。","朝浴扶桑腾浩荡，莫秣昆崙超象网。","雄姿似隘六合小，盛气欲籋浮云上。","嗅尘一喷惊肉飞，奋迅不受人间鞿。","岂惟万马羞欲死，直与八骏争先驰。","只今相者多举肥，叹息此图谁复知。","君不见王处冲，半生隐德真成痴。"]},{"t":"赋张秋泉真人所藏研山","f":"七言古诗","c":["泰山亦一拳石多，势雄齐鲁青巍峨。","此石却是小岱岳，峰峦无数生陂陀。","千岩万壑来几上，中有绝涧横天河。","粤从混沌元气判，自然凝结非镌磨。","人间奇物不易得，一见大叫争摩挲。","米公平生好奇者，大书深刻无差讹。","傍有小研天所造，仰受笔墨如圆荷。","我欲为君书道德，但愿此石不用鹅。","巧偷豪夺古来有，问君此意当如何。"]},{"t":"兔","f":"曲","c":["少年驰逐燕齐郊，身骑骏马如腾蛟。","耳后生风鼻出火，大呼讨来飞鸣?。","如今老大百忧集，拄杖徐行防喘急。","卷中见画眼为明，骥闻秋风双耳立。"]},{"t":"春寒","f":"五言律诗","c":["夜雨鸣高枕，春寒入敝袍。","时光自花柳，吾意岂蓬蒿。","失色黄金尽，知音白雪高。","山林隐未得，空觉此生劳。"]},{"t":"雪后同子俊游何山次韵四首 其三","f":"五言律诗","c":["兵革时犹动，山林日就荒。","子真思隐遁，詹尹问行藏。","有意随三饭，无人馈五浆。","远山湖外白，立马见微茫。"]},{"t":"雪后同子俊游何山次韵四首 其四","f":"五言律诗","c":["湍驶波翻雪，风生地出雷。","薄醪随意尽，寒气逼人来。","更欲明朝去，何妨迫暮回。","自怜非李广，醉尉莫相猜。"]},{"t":"早春","f":"五言律诗","c":["溪上春无赖，清晨坐水亭。","草芽随意绿，柳眼向人青。","初日收浓雾，微波乱小星。","谁歌采蘋曲，愁绝不堪听。"]},{"t":"重游弁山 其二","f":"五言律诗","c":["竹色迷行径，松声汹座隅。","水清花自照，风暖鸟相呼。","饮罢思棋局，歌长缺唾壶。","重来潇洒地，聊足慰须臾。"]},{"t":"次韵陈无逸中秋月食风雨不见","f":"五言律诗","c":["溪月当圆夜，看云起莫愁。","层阴连积水，伏雨暗清秋。","白璧难容玷，明珠不可求。","每因观节物，转觉此生浮。"]},{"t":"次韵子山登楼有感 其一","f":"五言律诗","c":["西北高楼好，登临望眼空。","弁山横雨外，笠泽浸天东。","计乏千金药，羞看百鍊铜。","只应将世事，都付酒杯中。"]},{"t":"次韵子山登楼有感 其二","f":"五言律诗","c":["怀古情何极，登危气尚雄。","江山一时胜，宇宙百年中。","翠袖愁空谷，绨袍受朔风。","超然高举意，决眦送孤鸿。"]},{"t":"次韵冯伯田秋兴 其二","f":"五言律诗","c":["风紧草木变，露寒沙水清。","萧兰嗟共悴，鶗鴂忍先鸣。","黄阁非吾事，青山不世情。","浩歌聊感激，裘马任肥轻。"]},{"t":"次韵冯伯田秋兴 其三","f":"五言律诗","c":["兴逐秋风发，愁随秋夜长。","系书阳鸟远，促织候虫忙。","世巳无刘表，家徒有孟光。","故衣寒未补，发箧动幽香。"]},{"t":"奉和帅初兄将归见简 其一","f":"五言律诗","c":["戴子文章伯，不为时所知。","朱弦非众听，白璧易群疑。","海树生秋早，江船度越迟。","莫愁千里别，要作百年期。"]},{"t":"奉和帅初兄将归见简 其二","f":"五言律诗","c":["我坐幽忧疾，非君谁与娱。","清谈忘日夜，高论到唐虞。","天地无青眼，江湖有白须。","客居宁郁郁，归兴托莼鲈。"]},{"t":"和周景远见寄二首 其一","f":"五言律诗","c":["四海多兄弟，交情子独亲。","方将寻舴艋，何意画麒麟。","簿领淹豪士，江湖著散人。","相看俱老大，喜见二毛新。"]},{"t":"送翟伯玉云南省都事","f":"五言律诗","c":["万里云南路，青山落照边。","省郎新紫绶，幕府旧红莲。","见面嗟吾晚，观文觉子贤。","只应清淑气，不受瘴溪烟。"]},{"t":"雨","f":"五言律诗","c":["摵摵众叶响，滋滋生意新。","知谁实挥洒，解使尽圆匀。","蛛网悬珠络，荷盘泻汞银。","喜凉生枕簟，愁润逼衣巾。"]},{"t":"次韵观复表兄见简 其二","f":"五言律诗","c":["载酒无人到，山园昼掩门。","泥深妨步屧，雨暗只空村。","每忆文园渴，难忘北海尊。","何当来就饮，听我抚桐孙。"]},{"t":"送董参政赴召","f":"五言古诗","c":["丹极飞明诏，锋车召老臣。","仲舒经术䆳，贾谊谠言陈。","偃革怀殊俗，安田慰远人。","公心如皦日，江国自熙春。","散乱堆床帙，萧飕满案尘。","诡随吾不忍，高卧理还伸。","入奏能回主，当言莫爱身。","衮衣瞻望重，丈席侍趍频。","铅椠工无益，樵渔意巳亲。","白鸥波万里，浩荡未能驯。"]},{"t":"投赠刑部尚书不忽木公","f":"五言古诗","c":["胄子何多士，明公特妙年。","诗书师法在，簪绂相门传。","曳履星辰上，分光日月边。","帝心知俊彦，群望属英贤。","大木明堂器，朱丝清庙弦。","吉人词自寡，君子德为先。","断狱阴功厚，优儒礼数偏。","我非天下士，人谓地行仙。","山好双游屐，溪清一钓船。","赋诗时遣兴，好客恨无钱。","政尔韦编绝，俄闻束帛戋。","风尘驱驲骑，霜雪洒鞍鞯。","别妇经春夏，离乡整四千。","家书愁展读，旅食困忧煎。","郎位蒙超擢，官曹幸接联。","屡闻哦鄙句，信或有前缘。","知己诚难遇，扪心益自怜。","樊中淹泽雉，春晚怨啼鹃。","骥病思丰草，鸿冥羡远天。","仁言如借便，白首向林泉。"]},{"t":"送夹谷公分省陕西","f":"五言古诗","c":["忆从长杨猎，于时始识公。","堂堂九尺干，落落万夫雄。","补衮弥缝密，能书点画工。","劳谦延士类，岂弟到儿童。","黄阁归人望，青云有父风。","驱驰常扈从，奏对每留中。","暂辍尚书履，荣分陕右弓。","秦山依昼锦，燕雪感秋蓬。","粉署趍承旧，瀛洲忝窃同。","因公动乡思，飞梦过江东。"]},{"t":"题杨司农宅刘伯熙画山水图","f":"五言古诗","c":["移得山川胜，坐来烟雾空。","窗中列远岫，堂上见青枫。","岩树参差绿，林花掩冉红。","鸟飞天路回，人去野桥通。","村晚留迟日，楼高纳快风。","琴尊会仙侣，几杖从儿僮。","疑听孙登啸，将无顾恺同。","微茫看不足，潇洒兴难穷。","碧瓦开莲宇，丹楼耸竹宫。","乱泉鸣石上，孤屿出江中。","藉甚丹青誉，益知书画功。","烦渠添钓艇，着我一渔翁。"]},{"t":"和姚子敬秋怀五首 其一","f":"七言律诗","c":["铜爵春深汉苑空，邯郸月冷照秦宫。","烟花楼阁西风里，锦绣湖山落照中。","河水南来非禹迹，冀方北去有唐风。","溪城秋色催迟莫，愁对黄云没断鸿。"]},{"t":"和姚子敬秋怀五首 其二","f":"七言律诗","c":["落日孤城动鼓鼙，愁中画角不胜吹。","山川萧瑟秋云净，草木凋伤莫雨悲。","多病马卿聊假日，数奇李广不逢时。","卷帘白水青山里，隐几无言有所思。"]},{"t":"和姚子敬秋怀五首 其四","f":"七言律诗","c":["吴宫烟冷水空流，惨澹风云暗九秋。","禾黍故基曾驻辇，芙蓉高阁迥添愁。","绣楹锦柱蛟龙泣，金沓瑶阶鹿豕游。","宋玉平生最萧索，欲将《九辩》赋离忧。"]},{"t":"和姚子敬秋怀五首 其五","f":"七言律诗","c":["野旷天高木叶疏，水清沙白鸟相呼。","胡笳处处军麾满，鬼哭村村汉月孤。","新亭举目山河异，故国伤神梦寐俱。","黄菊欲开人卧病，可怜三径巳荒芜。"]},{"t":"登飞英塔","f":"七言律诗","c":["梯飙直上几百尺，俯视层空鸟背过。","千里湖山秋色净，万家烟火夕阳多。","鱼龙衮衮危舟楫，鸿雁冥冥避网罗。","谁种山中千树橘，侧身东望洞庭波。"]},{"t":"次韵刚父无逸游南山作","f":"七言律诗","c":["绝顶清秋凌翠烟，登临应费酒如川。","平生能着几两屐，负郭何须二顷田。","初日出云光射地，双溪入湖波接天。","升高望远我所爱，青壁有路何当缘。"]},{"t":"次韵舜举春日感兴","f":"七言律诗","c":["沙头春日已喧妍，细柳新蒲色共鲜。","世事底须求分外，人生何物胜尊前。","飞花冉冉催华发，宿草青青失古阡。","回首旧欢如梦过，不知今日是何年！"]},{"t":"次韵章得一同原父侄游兰泽","f":"七言律诗","c":["绿树闇闇草接天，已愁春尽更闻鹃。","落花飞絮都成恨，痛饮狂歌浑欲颠。","起舞有人如谢尚，著书无意似伶玄。","绣筵宝瑟何时会，割锦缠头不计钱。"]},{"t":"见章得一诗因次其韵二首 其二","f":"七言律诗","c":["片片飞花欲送春，萋萋碧草正愁人。","黄蜂酿蜜经营急，紫燕衔泥来去频。","才似茂陵非晚遇，美如曲逆不长贫。","久知求富都无益，但喜论诗若有神。"]},{"t":"奉和帅初雨中见赠 其一","f":"七言律诗","c":["阴雨凄凄生夏寒，故人望望惜清欢。","停云底事能相阻，后土何时可得乾。","无事甘为犀首饮，切云聊着屈平冠。","闭门客散且高卧，户外泥深没马鞍。"]},{"t":"奉和帅初雨中见赠 其二","f":"七言律诗","c":["正坐清谈与世违，交情如子定应稀。","图书跌宕心犹在，裘马清狂意巳非。","黄鹤未知何日返，饥乌故作傍人飞。","溪南流水清如玉，终拟归休理钓矶。"]},{"t":"多景楼","f":"七言律诗","c":["层颠官阁几时脩，绕槛长江万古流。","白露巳零秋草绿，斜阳虽好莫云稠。","平南筹策张华得，治内人才葛亮优。","景物未穷登览兴，角声孤起瓮城秋。"]},{"t":"东阳八咏楼","f":"七言律诗","c":["山城秋色净朝晖，极目登临未拟归。","羽士曾闻辽鹤语，征人又见塞鸿飞。","西流二水玻瓈合，南去千峰紫翠围。","如此山川良不恶，休文何事不胜衣。"]},{"t":"金陵雨花台遂至故人刘叔亮墓","f":"七言律诗","c":["雨花台上看晴空，万里风烟入望中。","人物车书南北混，山川襟带古今同。","昆虫未蛰霜先陨，凤鸟不鸣江自东。","绿发刘伶缘醉死，往寻荒冢酹西风。"]},{"t":"蛾眉亭","f":"七言律诗","c":["天门日涌大江来，牛渚风生万壑哀。","青眼故人携酒共，两眉今日为君开。","苍崖直下蛟龙吼，白浪横空鹅鹳回。","南眺青山怀李白，沙头官渡苦相催。"]},{"t":"大都红门外海子上即事","f":"七言律诗","c":["白水青林引兴多，红裙翠黛奈愁何。","底从暮醉兼朝醉，聊复长歌更短歌。","轻燕受风迎落絮，老鱼吹浪动新荷。","馀不溪上扁舟好，何日归休理钓蓑？"]},{"t":"赠周景远田师孟","f":"七言律诗","c":["与子同客帝王州，一日不见如三秋。","风高气肃雁声急，天青日暖蛛丝游。","篱下黄花为谁好，水边红树令人愁。","世间万事可拨遣，日日痛饮醉即休。"]},{"t":"送缪秀才教授真州","f":"七言律诗","c":["髯生别我将安适，言向真州作教官。","但使清风生绛帐，何妨朝日照空槃。","东园草木因人胜，北固江山隔岸看。","才近中年巳伤别，可堪南望送归鞍。"]},{"t":"次韵左辖相公","f":"七言律诗","c":["昔年闾里自浮沉，郎省那知遂有今。","老去冯唐堪底用，愁来庄舄向谁吟。","上林柳色春犹浅，西塞桃花水正深。","知己如公居鼎鼐，不应长此泣南音。"]},{"t":"次韵左辖相公奉寄行台中丞徐公","f":"七言律诗","c":["尽日沉迷簿领书，何时重得赋閒居。","已无梦想悬金印，岂有文章到石渠。","白发故人霜柏在，黄尘游子断蓬如。","旧游忆在吴兴日，自采溪毛脍白鱼。"]},{"t":"送吴思可总管汀州","f":"七言律诗","c":["七闽南去路崎岖，五马承恩出帝都。","地气喜闻今有雪，民生宁似昔无襦。","山城酒美倾鹦鹉，雨馆春深听鹧鸪。","他日相思应怅恨，离筵不忍赋骊驹。"]},{"t":"至元庚辰繇集贤出知济南暂还吴兴赋诗书怀 其一","f":"七言律诗","c":["五年京国误蒙恩，乍到江南似梦魂。","云影时移半山黑，水痕新涨一溪浑。","宦途久有曼容志，㛰娶终寻尚子言。","政为疏慵无补报，非干高尚慕丘园。"]},{"t":"至元庚辰繇集贤出知济南暂还吴兴赋诗书怀 其二","f":"七言律诗","c":["多病相如巳倦游，思归张翰况逢秋。","鲈鱼莼菜俱无恙，鸿雁稻粱非所求。","空有丹心依魏阙，又携十口过齐州。","闲身却羡沙头鹭，飞去飞来百自由。"]},{"t":"刘端父御史见和初到济南诗次韵荅之","f":"七言律诗","c":["少日居多隐遁情，微官犹喜得山城。","腹中洞视浑无物，身外何因更有名。","忽忆放船苕水去，终期背郭草堂成。","故乡一别三千里，看见池塘草又生。"]},{"t":"趵突泉","f":"七言律诗","c":["泺水发源天下无，平地涌出白玉壶。","谷虚久恐元气泄，岁旱不愁东海枯。","云雾润蒸华不注，波涛声震大明湖。","时来泉上濯尘土，冰雪满怀清兴孤。"]},{"t":"继郑鹏南书怀","f":"七言律诗","c":["岂不怀归苦未闲，宦情羁思不成欢。","可能治郡如龚遂，只合临流似幼安。","棋局懒从先处着，医方留取用时看。","夜来梦到苕溪上，一枕清风五月寒。"]},{"t":"德清闲居","f":"七言律诗","c":["巳无新梦到清都，空有高情学隐居。","贫尚典衣贪购画，病思弃研厌求书。","圉人焚积夜防虎，溪女叩扉朝卖鱼。","困即枕书饥即饭，谋生自笑一何疏。"]},{"t":"题山堂","f":"七言律诗","c":["手种青松一万栽，山堂留得翠屏隈。","推窗绿树排檐入，临水红桃对镜开。","山雉雊迎朝日去，野禽啼傍夕阳来。","老妻亦有幽栖意，数日迟留不肯回。"]},{"t":"海子上即事与李子构同赋","f":"七言律诗","c":["小姬劝客倒金壶，家近荷花似镜湖。","游骑等閒来洗马，舞靴轻妙迅飞凫。","油云判污缠头锦，粉汗生怜络臂珠。","只有道人尘境静，一襟凉思咏风雩。"]},{"t":"重用韵","f":"七言律诗","c":["更从何处访蓬壶，花满平堤水满湖。","韩嫣金丸落飞鸟，王乔仙履下双凫。","姬姜自爱千金貌，游侠轻量一斛珠。","我老不知年少事，水边行散似春雩。"]},{"t":"送杜伯玉四川行省都事","f":"七言律诗","c":["浣花溪上草堂存，今见能诗几代孙。","橘刺藤梢隐丛竹，椒浆桂酒荐芳荪。","日长画省文书静，春近岷江雪浪奔。","我向东吴君向蜀，别离从古解销魂。"]},{"t":"次韵李秀才见赠","f":"七言律诗","c":["曾是先皇侍从班，龙髯飞去竟难攀。","重来赤日黄尘里，梦到清泉白石间。","岂有文章供世用，久判渔钓与云閒。","何当便理南归棹，呼酒登楼看弁山。"]},{"t":"送岳德敬提举甘肃儒学","f":"七言律诗","c":["苦欲留君君不留，奋髯跨马走甘州。","功名到手不可避，富贵逼人那得休。","春酒蒲萄歌窈窕，秋沙苜蓿饱骅骝。","儒冠也有封侯相，万里归来尚黑头。"]},{"t":"赠放烟火者","f":"七言律诗","c":["人间巧艺夺天工，鍊药燃灯清昼同。","柳絮飞残铺地白，桃花落尽满阶红。","纷纷灿烂如星陨，㸌㸌喧豗似火攻。","后夜再翻花上锦，不愁零乱向东风。"]},{"t":"题温雪峰诗迹","f":"七言律诗","c":["出拥旌麾一俊臣，归寻松竹作闲人。","龙蛇留遗人间世，泉石逍遥物外身。","自古神仙皆旷达，由来豪杰岂埃尘。","山川良是诸孙老，华表归来又几春。"]},{"t":"胜槩楼","f":"七言律诗","c":["楼下寒泉雪浪惊，楼前山色翠屏横。","登临何必须吾土，啸傲聊因得此生。","檐外白云来托宿，梁间紫燕语开情。","济南胜槩天下少，试倚阑干眼自明。"]},{"t":"老态","f":"七言律诗","c":["老态年来日日添，黑花飞眼雪生髯。","扶衰每藉齐眉杖，食肉先寻剔齿櫼。","右臂拘挛巾不裹，中肠惨戚泪常淹。","移床独就南荣坐，畏冷思亲爱日檐。"]},{"t":"弁山佑圣宫次孟君复韵","f":"七言律诗","c":["意行骑马到林间，晴雾都沈远近山。","琼树著花春自早，翠禽双语意相关。","一杯到手先成醉，万事无心触处閒。","犹欠抱琴来托宿，静中规写水潺潺。"]},{"t":"醉后同张刚父清风楼联句","f":"七言律诗","c":["碧树未黄风露秋，晚云萧瑟乱山愁。","千家疏雨催砧杵，两岸残阳入钓舟。","画角吹残人罢市，清尊饮散客登楼。","古今回首俱陈迹，唯有溪声日夜流。"]},{"t":"题秋山行旅图","f":"五言绝句","c":["老树叶似雨，浮岚翠欲流。","西风驴背客，吟断野桥秋。"]},{"t":"题萱草蛱蝶图","f":"五言绝句","c":["丛竹无端绿，幽花特地妍。","飞来双蛱蝶，相对意悠然。"]},{"t":"黄葵词","f":"五言绝句","c":["仙掌郁金衣，朝阳风露晞。","可怜蜂与蝶，秪解弄春晖。"]},{"t":"题太白酒船图 其二","f":"五言绝句","c":["萧洒稽山道，风流贺季真。","相思不相见，愁杀谪仙人。"]},{"t":"寄题真定明远亭","f":"五言绝句","c":["未到新亭上，先题明远诗。","云间归雁小，山外夕阳迟。"]},{"t":"独夜","f":"五言绝句","c":["秋风动林叶，夜雨滴池荷。","孤客睡不着，乱蛩鸣更多。"]},{"t":"题李仲宾野竹图","f":"五言绝句","c":["偃蹇高人意，萧疏旷士风。","无心上霄汉，混迹向蒿蓬。"]},{"t":"天冠山题咏二十二首 其一 龙口岩","f":"五言绝句","c":["峭石立四壁，寒泉飞两龙。","人间苦炎热，仙境已秋风。"]},{"t":"天冠山题咏二十二首 其四 长廊岩","f":"五言绝句","c":["脩岩如长廊，下有流泉注。","山中古仙人，步月自来去。"]},{"t":"天冠山题咏二十二首 其五 金沙岭","f":"五言绝句","c":["攀萝缘石磴，步上金沙岭。","露下色荧荧，月生光炯炯。"]},{"t":"天冠山题咏二十二首 其九 寒月泉","f":"五言绝句","c":["我尝游惠山，泉味胜牛乳。","梦想寒月泉，携茶就泉煮。"]},{"t":"天冠山题咏 其六 一线天","f":"五言绝句","c":["醯鸡舞瓮中，井蛙居坎底。","莫作一线看，开眼九万里。"]},{"t":"题周秀才此山堂 其一","f":"五言绝句","c":["青青云外山，烱烱松下石。","顾此山中人，风神照松色。"]},{"t":"晓起闻莺","f":"五言绝句","c":["暑气晓来清，时时闻远莺。","还思故园路，松下绿苔生。"]},{"t":"牧废苑","f":"五言绝句","c":["一片中原地，纷纷几战争。","至今将不去，留与后人耕。"]},{"t":"黄清夫秋江钓月图","f":"曲","c":["尘土染人衣袂，烟波着我船窗。","为问行歌都市，何如钓月秋江。"]},{"t":"题王子庆所藏大年墨雁","f":"曲","c":["鸿雁栖栖遵渚，黄芦索索鸣秋。","羡杀承平公子，笔端万里沧洲。"]},{"t":"初至都下即事 其二","f":"七言绝句","c":["尽日车尘马足间，偶来临水照愁颜。","故乡兄弟应相忆，同看溪南柳外山。"]},{"t":"送王月友归杭州 其二","f":"七言绝句","c":["云本无心漫出山，归来依旧与云闲。","何当从子东南去，扫地焚香昼掩关。"]},{"t":"清胜轩绝句","f":"七言绝句","c":["小草幽香动碧池，暖风晴日长新荑。","南窗昼倚绿阴静，听尽行人过马蹄。"]},{"t":"题东野平陵图","f":"七言绝句","c":["骑驴渺渺入荒城，积水空林坐自清。","政使不容投劾去，也胜尘土负平生。"]},{"t":"次韵刚父即事绝句 其一","f":"七言绝句","c":["玉树凋伤众草黄，夜虫时语怨流光。","美人望望隔秋水，不寄相思书一行。"]},{"t":"次韵刚父即事绝句 其二","f":"七言绝句","c":["凄凉鼓角北风传，嘈杂琵琶思远天。","白雪有谁知幼眇，翠蛾空自惜联娟。"]},{"t":"次韵刚父即事绝句 其三","f":"七言绝句","c":["摇落山川树影稀，陇云时逐雁南飞。","苦无渌酒酬佳节，犹有黄花媚夕晖。"]},{"t":"戏题僧惟尧墨梅","f":"七言绝句","c":["萧洒孤山半树春，素衣谁遣化缁尘。","何如澹月微云夜，照影西湖自写真。"]},{"t":"题范蠡五湖杜陵浣花 其一","f":"七言绝句","c":["功名自古是危机，谁似先生早拂衣。","好向五湖寻一舸，霜黄木叶雁初飞。"]},{"t":"题范蠡五湖杜陵浣花 其二","f":"七言绝句","c":["春色醺人苦不禁，蹇驴驮醉晚骎骎。","江花江草诗千首，老尽平生用世心。"]},{"t":"梅花","f":"七言绝句","c":["潇洒江梅似玉人，倚风无语澹生春。","曲中桃叶元非侣，梦里梨花恐未真。"]},{"t":"送王子庆诏檄浙东收郡县图籍 其一","f":"七言绝句","c":["木落江南天地秋，西风吹子过东州。","试开图籍寻佳处，便命舟车作胜游。"]},{"t":"题龚圣予山水图 其一","f":"七言绝句","c":["泽雉樊中神不王，白鸥波上梦相亲。","黄尘没马归来晚，只有西山小慰人。"]},{"t":"题龚圣予山水图 其二","f":"七言绝句","c":["当年我亦画云山，云白山青只尺间。","今日看山还自笑，白头输与楚龚闲。"]},{"t":"杭州雨中","f":"七言绝句","c":["江南十日九阴雨，花柳欲开无好春。","却忆京城二三月，秋千风暖涨香尘。"]},{"t":"题舜举折枝桃","f":"七言绝句","c":["醉里春归寻不得，眼明忽见折枝花。","向来飞盖西园夜，万烛高烧照烂霞。"]},{"t":"怀德清别业 其一","f":"七言绝句","c":["阳林堂下百株梅，傲雪凌寒次第开。","枝上山禽晓啁哳，定应唤我早归来。"]},{"t":"部中暮归寄周公谨 其一","f":"七言绝句","c":["日莫空街生白烟，归来羸马不胜鞭。","明朝又逐鸡声起，孤负日高花影眠。"]},{"t":"部中暮归寄周公谨 其二","f":"七言绝句","c":["三年谩仕尚书郎，梦寐无时不故乡。","输与钱唐周老子，浩然斋里坐焚香。"]},{"t":"都南张氏园寓居","f":"七言绝句","c":["尺五城南迹似幽，乡心空折大刀头。","杏花飞尽燕脂雪，日日东风未肯休。"]},{"t":"和黄景杜雪中即事 其二","f":"七言绝句","c":["雪寒凄切透书帷，极目南云入望低。","欲报平安无过雁，忽惊残梦有鸣鸡。"]},{"t":"和黄景杜雪中即事 其三","f":"七言绝句","c":["君说江南苦未归，香橙新酒蟹螯肥。","何当与子扁舟去，共挽清溪浣客衣。"]},{"t":"和黄景杜雪中即事 其四","f":"七言绝句","c":["客里相从意最亲，高歌快饮见天真。","明年去学潘怀县，满县栽花做好春。"]},{"t":"和黄景杜雪中即事 其五","f":"七言绝句","c":["当年临水照春衫，浮玉山前水似蓝。","归计未成羁思恶，为君飞梦到城南。"]},{"t":"湖上莫归 其一","f":"七言绝句","c":["春阴柳絮不能飞，雨足蒲芽绿更肥。","政恐前呵惊白鹭，独骑款段绕湖归。"]},{"t":"即事三绝 其一","f":"七言绝句","c":["湘帘疏织浪纹稀，白苧新裁暑气微。","庭院日长宾客退，绕池芳草燕交飞。"]},{"t":"即事三绝 其二","f":"七言绝句","c":["古墨轻磨满几香，研池新浴照人光。","北窗时有凉风至，闲写黄庭一两章。"]},{"t":"咏逸民十一首 其三","f":"五言古诗","c":["驱车秣驽马，吾将适齐国。","闻有鲁连子，俶傥好奇画。","一谈秦师走，再说聊城拔。","功成不受赏，高举振六翮。","布衣终其身，岂复为世役。","茫茫千载远，安往访遗迹。","踌躇东海上，向风长太息。"]},{"t":"咏逸民十一首 其四","f":"五言古诗","c":["四时相代谢，荣耀何足恃。","瓜田引新蔓，不见桃与李。","知士解其会，遇坎当复止。","邵生故秦吏，乃亦睹兹理。","贤哉感我怀，三叹不能巳。"]},{"t":"咏逸民十一首 其五","f":"五言古诗","c":["子真初亦仕，岁晚乃逃之。","区区南昌尉，上疏忘其卑。","忠言不见用，耿耿当告谁。","飘然弃妻子，终身与世辞。","抱关甘贫贱，所贵莫我知。","至今九江濆，清风激群黎。","神仙信茫昧，此士独不疑。","孤云无定在，逝水何时归。","遐思一矫首，怅望无由期。"]},{"t":"咏逸民十一首 其六","f":"五言古诗","c":["悠悠空山云，泱泱长江流。","廊庙意不屑，山泽聊淹留。","故人在天位，高步追巢由。","岂曰子无衣，辛苦被羊裘。","东京多节义，之子乃其尤。","穷居虽独善，辅世岂不优。"]},{"t":"咏逸民十一首 其七","f":"五言古诗","c":["汪汪千顷陂，不为人浊清。","道周言行表，荡然无得名。","谁言牛医儿，乃是人中英。","当时无间言，后世流德声。","思之不可见，使我鄙吝萌。","淳风久已漓，此意岂复明。","时无君子者，虽贤宁见称。"]},{"t":"咏逸民十一首 其八","f":"五言古诗","c":["南州有高士，食力事耕稼。","优游聊卒岁，不矫亦不隘。","大木行欲颠，绋纚岂足赖。","何为诸老翁，栖栖不遑舍。","斯言非无见，明哲自高迈。","谁能悬一榻，待子来税驾。"]},{"t":"咏逸民十一首 其九","f":"五言古诗","c":["鹿门何亭亭，下有辟世贤。","凤雏隐中林，卧龙蟠其渊。","一朝起高翔，斯人独深潜。","功名不可为，我志久已安。","一闻耆旧传，使我心悠然。"]},{"t":"咏逸民十一首 其十","f":"五言古诗","c":["黄鹄羽翼长，一举思千里。","幼安本中原，乘桴走东海。","举世方尚同，远引存吾志。","流风渐异俗，敦礼化邻鄙。","子鱼平生友，胡乃不相委。"]},{"t":"咏逸民十一首 其十一","f":"五言古诗","c":["尘事非所便，田园久见招。","归来三径中，蔚蔚长蓬蒿。","虽有荷锄倦，浊酒且自陶。","茫茫大化中，委运将焉逃。","唐虞去已远，由来非一朝。","粲粲霜中菊，采采忘其劳。"]},{"t":"次袁学士上都诗韵","f":"五言律诗","c":["晓日夹云树，春风吹雪山。","飞鹰玄兔碛，饮马白狼湾。","宝带吴钩迥，金矛汉节閒。","将军万里外，不怕二毛斑。"]},{"t":"送陈都事云南铨选兼简李廉访","f":"七言律诗","c":["送君铨选使滇池，部落诸夷自品题。","明月梦回夔子北，长风吹度夜郎西。","山连塞雨骅骝滑，花落蛮云杜宇啼。","为问霜台李学士，白头官满尚羁栖。"]},{"t":"杭州拱北楼","f":"七言律诗","c":["城上高楼接太霞，令严钟鼓静无哗。","提封内向三千里，比屋同封百万家。","心在江湖存魏阙，身随牛斗泛仙槎。","举头便觉长安近，时倚阑干望日华。"]},{"t":"赠脱帖木儿总管","f":"七言律诗","c":["将军铁马拥雕弓，壮岁分符镇越中。","山水多情留贺监，儿童拍手爱山公。","紫髯似戟君犹健，白发如丝我巳翁。","悦礼敦诗殊不忝，看君真有古人风。"]},{"t":"和姚子敬韵","f":"七言律诗","c":["同学故人今已稀，重嗟出处寸心违。","自知世事都无补，其奈君恩未许归。","沧洲白鸟时时梦，玉带金鱼念念非。","准拟明年乞身去，一竿同理旧苔矶。"]},{"t":"题孙登长啸图","f":"七言绝句","c":["在涧幽人乐考槃，南山白石夜漫漫。","空林无风万籁寂，长啸一声山月寒。"]},{"t":"咏史","f":"七言绝句","c":["酒酣斫剑气如云，屠狗吹箫尽策勋。","汉室功臣谁第一，黄金合铸纪将军。"]},{"t":"宫中口号 其一","f":"七言绝句","c":["日照黄金宝殿开，雕阑玉砌拥层台。","一时侍卫回身立，天步将临玉斧来。"]},{"t":"题四画 其三 四皓","f":"七言绝句","c":["白发商岩四老翁，紫芝歌罢听松风。","半生不与人间事，亦堕留侯计术中。"]},{"t":"偶成 其一","f":"七言绝句","c":["竹林深处小亭开，白鹤徐行啄紫苔。","羽扇不摇纱帽侧，晚凉青鸟忽飞来。"]},{"t":"即事 其一","f":"七言绝句","c":["庭槐风静绿阴多，睡起茶馀日影过。","自笑老来无复梦，閒看行蚁上南柯。"]},{"t":"讥留梦炎诗","f":"七言绝句","c":["状元曾受宋家恩，国困臣强不尽言。","往事已非那可说，且将忠直报皇元。"]},{"t":"赠子敬","f":"五言绝句","c":["吾爱子姚子，风流如晋人。","白眼视四海，清谈无一尘。"]},{"t":"题所画梅竹赠石民瞻 其一","f":"七言绝句","c":["故人赠我江南句，飞尽梅花我未归。","欲寄相思无别语，一枝寒玉澹春晖。"]},{"t":"万柳堂即席","f":"七言律诗","c":["万柳堂前数亩池，平铺云锦盖涟漪。","主人自有沧洲趣，游女仍歌白雪词。","手把荷花来劝酒，步随芳草去寻诗。","谁知咫尺京城外，便有无穷万里思。"]},{"t":"题圆泽三生公案","f":"七言绝句","c":["川上清风非有著，松间明月本无尘。","不知二子缘何事，苦恋前身与后身？"]},{"t":"绝句","f":"楚辞体","c":["轻轻踏破白云堆，半为寻僧半探梅。","僧不逢兮梅未放，野猿笑我却空回。"]},{"t":"题息斋竹","f":"七言绝句","c":["李侯写竹有清气，满纸墨光浮翠筠。","萧郎已远丹渊死，欲写此君惟此人。"]},{"t":"送王月友归杭州 其一","f":"七言绝句","c":["社燕秋鸿各自飞，我来君去苦相违。","西湖西畔梅如雪，应有亲朋待子归。"]},{"t":"酬罗伯寿 其一","f":"七言绝句","c":["江西水清石凿凿，士生其间多异才。","今去欧黄未为远，要须力挽古风回。"]},{"t":"游补陀","f":"七言律诗","c":["缥缈云飞海上山，挂帆三日上潺湲。","两宫福德齐千佛，一道恩光照百蛮。","涧草岩花多瑞气，石林水府隔尘寰。","鲰生小技真荣遇，何幸凡身到此间。"]},{"t":"题彦敬越山图","f":"五言绝句","c":["越山隔涛江，风起不可渡。","时於图中看，居然在烟雾。"]},{"t":"获周丰鼎见博古图第三卷铭六字","f":"五言律诗","c":["丰鼎制特小，周人风故淳。","摩挲玉质润，拂拭翠光匀。","铸法观来妙，铭文考更真。","平生䔍好古，对此兴弥新。"]},{"t":"筇竹杖赠天圣长老仁公仁有诗次其韵","f":"五言律诗","c":["瘦节苍骨耸，腻肤黄玉温。","苔间时卓地，月下屡敲门。","持赠松庐老，携寻水竹村。","归来倚空壁，夜气与俱存。"]},{"t":"采桑曲","f":"七言绝句","c":["野雉朝雊雊且飞，谁家女儿采桑归。","欲折花枝插丫髻，还愁草露湿裳衣。"]},{"t":"天冠山题咏二十二首 其二 洗药池","f":"五言绝句","c":["真人栖隐处，洗药有清池。","金丹要沐浴，玉水自生肥。"]},{"t":"古风十首 其一","f":"五言古诗","c":["诗亡春秋作，仲尼盖苦心。","空言恐难托，指事著以深。","大义炳如日，万古仰照临。","凤鸟久不至，楚狂乃知音。","愁来不得语，起坐弹吾琴。"]},{"t":"古风十首 其二","f":"五言律诗","c":["周衰有战国，纷纷极荆蓁。","黄金聘辩士，驷马迎从人。","朝为刻骨雠，莫作歃血亲。","终然智力屈，奉身俱入秦。"]},{"t":"古风十首 其三","f":"五言律诗","c":["相如赋大人，出语颇奇怪。","飘然凌云意，过耳诚一快。","誇言入无际，自觉尘俗隘。","安知翻成劝，何用名为戒。"]},{"t":"古风十首 其四","f":"五言律诗","c":["自有天地来，蓬莱几清浅。","人生空皓首，举世谁得见。","瑶台在何许，渺渺烟波远。","方舟不可渡，使我空展转。"]},{"t":"古风十首 其五","f":"五言古诗","c":["绝代有佳人，被服绮与纨。","蛾眉秀联娟，吐词馥若兰。","清歌启皓齿，瑶琴发哀弹。","一弹再三叹，听者涕汍澜。","借问谁家子，为言本邯郸。"]},{"t":"古风十首 其六","f":"五言古诗","c":["秋风吹庭树，故叶纷以队。","明月耿夜长，草虫促经纬。","四序苦不淹，少壮何足贵。","展转复展转，寤辟不能寐。","昔为闺中秀，今作市门鄙。","岂无膏与沐，甘心得憔悴。"]},{"t":"古风十首 其七","f":"五言古诗","c":["山深多悲风，日莫愁我心。","玄云降寒雨，松柏自哀吟。","人生百年后，奄然閟重阴。","念此每不乐，天路何由寻。","仙人偓佺辈，消摇在青岑。","奈何不尔思，委命重黄金。"]},{"t":"古风十首 其八","f":"五言古诗","c":["海山有奇树，粲粲珊瑚枝。","由来植物性，无胫可推移。","如何石氏子，树之白玉墀。","洛阳经几战，金谷久荒夷。","空令千载下，闻者为伤悲。"]},{"t":"古风十首 其九","f":"五言古诗","c":["烈风号枯条，落叶满周道。","原野何萧索，川流亦浩浩。","离居日以远，怀思令人老。","功名会有时，生世苦不早。","顾瞻靡所骋，忧心惄如捣。"]},{"t":"古风十首 其十","f":"五言古诗","c":["浮云何方来，不知竟安之。","飘飖随风去，汗漫以为期。","自昔功名士，往往事驱驰。","白驹空谷中，谁能加絷维。","皎皎难见容，翻受世妍媸。","虚名诚无益，不见斗与箕。"]},{"t":"和子俊感秋五首 其一","f":"五言古诗","c":["秋至倏廿日，天宇豁然清。","凉飙旦夕至，林木发商声。","良辰不我与，慨然心自惊。","古人久已逝，念之动中情。","苦心婴世患，只博身后名。","今我将无同，庶复得此生。"]},{"t":"和子俊感秋五首 其三","f":"五言古诗","c":["披衣步中庭，仰视河汉白。","寓形天地内，聊复度朝夕。","仲尼谅非愚，皇皇不暖席。","履运有异同，喟然慨今昔。","丘园岂云远，终当期屏迹。","日月驰骛去，鸟影飞过隙。","归休盍不早，胡为受形役。"]},{"t":"和子俊感秋五首 其四","f":"五言古诗","c":["微霄暧高宇，轻飙弄微凉。","天气政尔佳，抚己徒自伤。","今日非昨日，荏苒叹流光。","几见春鸟鸣，巳复啼寒螀。","一时良亦短，万世则为长。"]},{"t":"咏怀六首 其一","f":"五言古诗","c":["皇天分四序，寒暑互推移。","如何当秋夕，怆恍令心悲。","寒蝉寂无声，翔雁纷南飞。","西风一披拂，草木失华滋。","不惜鶗鴂鸣，但伤众芳萎。","徘佪白露下，郁邑谁能知。"]},{"t":"咏怀六首 其二","f":"五言古诗","c":["美人涉江来，遗我云和琴。","朱丝縆玉轸，古意一何深。","长歌和清弹，三叹有遗音。","逸响随风发，高高不可寻。","奈何俚俗耳，折杨悦哀淫。","此道弃捐久，沉吟独伤心。"]},{"t":"咏怀六首 其三","f":"五言古诗","c":["明明秋夜月，流光照罗帷。","隐忧从中来，起视夜何其。","草虫催杼轴，扎扎鸣声悲。","良人远行役，万里归无期。","予发巳曲局，膏沐久不施。","回身入闺房，愁思当告谁。","独有中宵梦，遥遥为君驰。"]},{"t":"咏怀六首 其四","f":"五言律诗","c":["苍天高无极，大川广且深。","下有沉潜鱼，上有冥飞禽。","先民莫不逸，我独怀苦心。","抒情作好歌，歌竟意难任。"]},{"t":"咏怀六首 其五","f":"五言律诗","c":["陵苕何青青，上蒙松与柏。","一时良亦好，岁晚竟谁得。","人无金石寿，生年不盈百。","何为慕荣禄，抱此长戚戚。"]},{"t":"咏怀六首 其六","f":"五言律诗","c":["菽粟在中原，夫人能采之。","无为思百忧，欢乐当及时。","今日忽已过，来日非所知。","有酒且复饮，既醉歌令仪。"]},{"t":"咏逸民十一首 其一","f":"五言古诗","c":["凤凰览德辉，奋翅翔千仞。","矫矫孤竹子，求仁斯得仁。","於心有不厌，视世等埃尘。","俯仰志不屈，又不辱其身。","圣言一以宣，万古无缁磷。","谁言首阳山，卓与嵩华邻。","采采山中薇，愧尔肉食人。"]},{"t":"咏逸民十一首 其二","f":"五言古诗","c":["劳生本非情，禄仕吾不苟。","古来畎亩间，亦有沮溺叟。","依依偶耕心，千载思尚友。","中道世所难，狂狷诚足取。","如何绝代下，相知不忠厚。","仲尼不复作，斯怀向谁道。"]},{"t":"岁莫和刚父杂诗四首 其一","f":"五言古诗","c":["穷阴结严寒，玄景閟微阳。","兰萧同憔悴，隐恻我中肠。","美人弹玉琴，继之歌清商。","弦急声未巳，知子意独长。","阳春时未至，此曲徒悲伤。"]},{"t":"岁莫和刚父杂诗四首 其二","f":"五言古诗","c":["美玉处荆山，林木生光辉。","采之献凡目，弃置亦其宜。","如何和氏子，涕泣有馀悲。","古来贤达人，不为毁誉移。","被褐怀至宝，宁惧不我知。","待贾未能信，韫藏诚可师。"]},{"t":"赠道隆上人","f":"五言古诗","c":["辟俗无所之，步寻招提游。","颓垣蔽蓬艾，破屋坏不脩。","老僧俗念净，静坐百不忧。","浮云有逸态，止水无急流。","乃知我辈人，苦受世累囚。","朅来得此地，稍觉心休休。","窗前几丛菊，青蕊亦巳稠。","爱之不忍采，留作山房秋。","何当移四松，伴汝成清幽。","南冈与北岭，路近颇易求。","他年风雨夜，来听龙吟愁。"]},{"t":"游南山憩山下人家和人韵","f":"五言古诗","c":["驱马南山阳，下马望绝巘。","解衣坐盘桓，言就蓬庐偃。","非无攀援力，兴尽自应返。","天高暄风息，木落岁华晚。","势阻乏遐观，趣得心自远。","不有君子词，何用抒缱绻。"]},{"t":"春后多阴偶成三首用复无逸来贶 其一","f":"五言古诗","c":["日出晨景澹，散发步中庭。","仰见濯濯柳，春风畅人情。","兹晨岂不佳，谁能定阴晴。","人生亦良脆，疲劳竟何营。","万事可拨遣，舍道焉求成。"]},{"t":"春后多阴偶成三首用复无逸来贶 其二","f":"五言古诗","c":["卧起向北窗，一室可栖迟。","取诗三百萹，一一弦歌之。","古道岂为远，先师不吾欺。","嘉我有良朋，所志共在兹。","适意聊娱乐，过此非所知。"]},{"t":"春后多阴偶成三首用复无逸来贶 其三","f":"五言律诗","c":["仲春忽已过，四序随流波。","水深不可厉，苦雨一何多。","田园颇在念，春事今如何。","沉忧亦无益，言笑复言歌。"]},{"t":"晓起川上赠友","f":"五言古诗","c":["明发不能寐，独步柳阴中。","秋色方浩荡，晨光乍曈昽。","烁烁川上日，萧萧树间风。","葛巾吹欲堕，纤絺巳无功。","感彼岁月驶，悟此人世空。","悠悠竟何补，山林情所钟。","终期抗高志，驾言从赤松。"]},{"t":"游弁山","f":"五言古诗","c":["我欲到斯境，岁月良已深。","今晨为兹游，酬我夙昔心。","悠悠冈坂长，惨惨风云阴。","微雨迫短日，飘然洒衣襟。","娄欲还吾驾，去意复难任。","逍遥得所止，林竹自萧森。","素琴不须弹，山水有清音。","邈在樊笼外，尘想何由侵。","况怀冥绝理，去此将焉寻。","他山岂不好，聊尔非所钦。"]},{"t":"二月二日尊经阁望郊外山水二首 其一","f":"五言古诗","c":["朝登西北楼，遐景舒我怀。","熹微晨光动，窈窕春增华。","草木罕悴色，山川一何佳。","悠然斜川意，千载与我谐。","及兹春服成，言咏乐无涯。","此理将不泯，弃之良可嗟。"]},{"t":"二月二日尊经阁望郊外山水二首 其二","f":"五言古诗","c":["日出群动作，鸡犬亦复喧。","渺渺孤舟发，翩翩栖鸟迁。","先师有明训，政在善利间。","结发事诗书，於今益可怜。","况兹去古远，淳风未易还。","吾行亦聊尔，一览可忘言。"]},{"t":"次韵舜举四慕诗","f":"五言古诗","c":["子晰有高志，悠然舞雩春。","接舆谅非狂，行歌归隐沦。","周也实旷士，天地视一身。","去之千载下，渊明亦其人。","归来北窗里，势屈道自伸。","仕止固有时，四子乃不泯。","九原如可作，执鞭良所欣。"]},{"t":"春思","f":"五言古诗","c":["春柳黄如鹅，春风扬绿波。","美人在何许，忽若阻山阿。","攀条弄白日，常恐岁蹉跎。","怀思郁不舒，佳期将奈何。","良辰难骤得，临风空浩歌。"]},{"t":"杂诗","f":"五言古诗","c":["四时更代谢，物化常随之。","春华曾几何，岁月忽如兹。","严风动高林，百草具巳萎。","人生况有役，忧患乃其宜。","弃捐勿复念，出入由化机。","安得松乔术，邈与世相违。"]},{"t":"廉山晓行","f":"五言古诗","c":["曳杖行墟曲，苍茫晓色分。","凝霜被原隰，葛屦非昔闻。","新松夹道周，宿草冒高坟。","日月迭而逝，死生安足云。","轻舟沿寒流，怅望廉山云。","世固不可辟，斯人本同群。","缅焉心如结，咏言著斯文。"]},{"t":"奉和本斋先生首夏即事","f":"五言古诗","c":["天道虽不言，坐觉四时行。","蔼蔼庭前阴，烨烨枝上荣。","閒居有真趣，曲肱寄馀情。","仰视浮云翔，俯聆时鸟鸣。","道胜心自怡，松乔可齐龄。","惜哉无旨酒，为公称兕觥。"]},{"t":"赠赵虞卿","f":"五言古诗","c":["客从北方来，逍遥江湖间。","顾影空自爱，不见欣戚颜。","奕秋去已远，神观一朝还。","惜无双白璧，尉子行路难。","翩翩云中鹤，孤高杳难攀。","长怀紫霞客，引袂入名山。"]},{"t":"题董元溪岸图","f":"五言古诗","c":["石林何苍苍，油云出其下。","山高蔽白日，阴晦复多雨。","窈窕溪谷中，邅回入洲溆。","冥冥猿狖居，漠漠凫雁聚。","幽居彼谁子，孰与玩芳草。","因之一长谣，商声振林莽。"]},{"t":"赠别夹谷公二首 其一","f":"五言古诗","c":["驱马原隰间，经时不遑休。","昔来日在斗，今去麦己秋。","王事有埤益，宴安非所求。","翩翩晨风翼，一举逝莫留。","谁令匏瓜系，自怀离别忧。"]},{"t":"赠别夹谷公二首 其二","f":"五言古诗","c":["青青蕙兰花，含英在中林。","春风不披拂，胡能见幽心。","相去千里馀，会合大江南。","促席谈自古，知我一何深。","此别虽非远，怀思渺难任。","公其爱体素，尚无金玉音。"]},{"t":"题舜举小隐图","f":"五言古诗","c":["有水清且泚，洄洑乱石间。","乐哉三子者，在涧歌考槃。","流波牵弱缕，轻飙动文竿。","信无吞舟鱼，我志匪鲂鳏。","勿言隐尚小，神情有馀闲。","高士不可见，古风何时还。"]},{"t":"赵村道中 其二","f":"五言古诗","c":["昔年干戈动，兵尘暗三吴。","长江巳无险，智勇亦难图。","筑垒依平山，谋国一何愚。","桢干群林空，遗址莽丘墟。","至今蓬蒿下，犹有白骨枯。","天阴万鬼哭，惨惨荒山隅。","兴亡自有数，不敢问何如。","独怜野菊花，立马为踌躇。"]},{"t":"奉詶戴帅初架阁见赠二首 其二","f":"五言古诗","c":["吾爱戴安道，隐居绝埃尘。","弹琴聊自娱，书画又绝伦。","岂无召我者，已矣非所欣。","昔我道剡中，山川自清新。","是时夜雪霁，怀哉见其人。","常欲以暇日，慷慨为写真。","之子有祖风，千里响然臻。","我从苏李后，敢言笔墨神。","坐之盘石上，俗物不得亲。","微君动高兴，此意当谁陈。"]},{"t":"送周正平学士致仕还里","f":"五言古诗","c":["关吏晨启门，㒒夫戒首途。","祖道京城南，喜色动闉阇。","仕宦非徒荣，出处贵合义。","公今虽未耄，进退有馀地。","高蹈激流俗，清风耸朝廷。","增秩仍继禄，圣明优老成。","逍遥桑梓间，年高德弥邵。","红颜醉春酒，白发照晴昊。","两疏真勇决，四皓甘隐沦。","汉史不专美，古今凡几人。","青牛当南游，紫气巳先路。","我欲强著书，怀哉未能去。"]},{"t":"寄鲜于伯几","f":"五言古诗","c":["廊庙不乏才，江湖多隐沦。","之子称吏隐，才高非众邻。","脱身轩冕场，筑屋西湖滨。","开轩弄玉琴，临池书练裙。","雷文粲周鼎，鹿鸣娱嘉宾。","图书左右列，花竹自清新。","赋诗凌鲍谢，往往绝埃尘。","我生少寡谐，一见夙昔亲。","误落尘网中，四度京华春。","泽雉叹畜樊，白鸥谁能驯。"]},{"t":"送程子充运副之杭州","f":"五言古诗","c":["盐为生民食，日用犹水火。","虽非饥所急，一日无不可。","但令商贾便，那复愁国课。","数年人坏法，贪欲肆偏颇。","利多归私室，民始受盐祸。","尔来又计口，强致及包裹。","㩁酤穷滴沥，征商剧遮逻。","东南民力竭，此事非细琐。","朝家更政化，选择堪负荷。","君为尚书郎，精白色瑳瑳。","明当戒行李，往理吴越柂。","祝君无别语，编户要安妥。","湖山多胜处，亦可供宴坐。","谈笑尊俎间，佳声满江左。"]},{"t":"赠茅山梁道士","f":"五言古诗","c":["名山标勾曲，秀岭蔚层云。","层云散浩彩，中有三茅君。","度世三千秋，流芳浩无垠。","丹光耀朱阳，琴心传玉文。","司命播万物，发蒙导人群。","学道得旷士，采真遗尘氛。","赠我书一编，清谣吐奇芬。","笔耕亦巳勤，寸田要锄耘。","灵台耸绛阙，黄云覆氤氲。","内观神自照，众言一何纷。","平生山林意，独往乃所欣。","攀援桂树枝，采撷芝兰薰。","静与木石居，游则侣麋麇。","松柏无冬夏，烟霞自夕昕。","轩冕或桎梏，绮语徒膻荤。","大道返尔朴，至哉吾师云。","冥冥紫霞想，湛言久不闻。","聆我歌洞章，判然仙凡分。"]},{"t":"次韵齐彦学士中秋雨后玩月","f":"五言古诗","c":["卧痾愧微官，俯仰百忧集。","安知中秋至，但见明月出。","萧萧雨新巳，凉气澄霁夕。","青旻罗疏星，灿若殊与璧。","小虫鸣草根，万物皆自适。","而我独何为，矫首望南北。","愁来无端倪，拨去终不释。","人生莫不乐，杯酒会邻戚。","高歌杂清唱，起舞戛鸣瑟。","闭户且复眠，空尊何由酌。"]},{"t":"秋日锦樱为继卿作","f":"五言古诗","c":["灼灼庭下花，霜馀发春妍。","众卉方具腓，秾芳独嫣然。","主人远方来，一笑清尊前。","植物岂无情，有开容必先。","造化寓深意，嘉与后人传。"]},{"t":"听姜伯惠父弹琴擘阮","f":"五言古诗","c":["姜子早闻道，澹然遗世荣。","蓺花有生意，焚香无俗情。","时抱琴与阮，弹作松风声。","畴昔江湖间，久巳知子名。","安知十年后，一笑成合并。","是邦山水秀，照人肌骨清。","愿子石泉上，为鼓一再行。","因之洗吾耳，遂欲濯尘缨。"]},{"t":"题洞阳徐真人万壑松风图","f":"五言律诗","c":["谡谡松下风，悠悠尘外心。","以我清净耳，听此太古音。","逍遥万物表，不受世故侵。","何年从此老，辟谷隐云林。"]},{"t":"自释","f":"五言古诗","c":["君子重道义，小人贵功名。","天爵元自尊，世纷何足荣。","乘除有至理，此重彼自轻。","青松与蔓草，物情当细评。","勿为蔓草蕃，愿作青松贞。"]},{"t":"送石仲璋","f":"五言古诗","c":["霜风何凄厉，兰萧同枯萎。","念此鼻为酸，恻怆中心悲。","由来无丑好，众女嫉蛾眉。","数罟困巨鱼，盐车厄天骐。","况复值怨仇，贝锦成祸机。","俯首无所诉，菹醢听所为。","向非知己者，虽死谁明之。","君子有行役，后会在何时。","欲别不敢往，瞻望涕涟洏。","援笔抚我心，为公吐此词。"]},{"t":"题桃源图","f":"五言古诗","c":["战国方忿争，嬴秦复狂怒。","冤哉鱼肉民，死者不知数。","斯人逃空谷，是殆天所恕。","山深无来遥，林密绝归路。","艰难苟生活，种莳偶成趣。","西邻与东舍，鸡犬自来去。","熙熙如上古，无复当世虑。","安知捕鱼郎，延缘至其处。","遥遥千载后，缅想增慨慕。","即今生齿繁，险绝悉开露。","山中无木客，川上靡渔父。","虽怀隐者心，桃源在何许。","况兹太平世，尧舜方在御。","干戈久己戢，老幼乐含哺。","田畴毕耕耨，努力勤蓻树。","毋为问迷津，穷探事高举。"]},{"t":"题李伯时元祐内厩五马图黄太史书其齿毛","f":"五言古诗","c":["五马何翩翩，萧洒秋风前。","君王不好武，刍粟饱丰年。","朝入阊阖门，莫秣十二闲。","雄姿耀朝日，灭没走飞烟。","顾盻增意气，群龙戏芝田。","骏骨不得朽，托兹书画传。","誇哉昭陵石，岁久当颓然。"]},{"t":"酬滕野云","f":"五言古诗","c":["滕君本臞儒，肝鬲足清气。","赋诗多秀句，往往含古意。","大誇江山美，一洗尘土翳。","平生有诗癖，得句时自憙。","尔来荒芜甚，枯涩常内愧。","锦绣忽堕前，令我喜不寐。","功名亦何有，富贵安足计。","唯有百年后，文字可传世。","霅溪春水生，归志行可遂。","閒吟渊明诗，静学右军字。","但恐君未閒，书成无由寄。"]},{"t":"述太傅丞相伯颜功德","f":"曲","c":["兴癈本天运，辅成见人庸。","舆地久以裂，车书会当同。","先帝昔在御，如日行虚空。","六合仰照耀，一方顾颛蒙。","授钺得人杰，止戈代天工。","铁马浮度江，坐收破竹功。","草木纷震动，山川变鸿?。","地利不复险，金城何足攻。","市靡易肆忧，兵无血刃红。","孰能年岁间，伐国究始终。","老稚感再生，遗黎忘困穷。","归来一不取，匹马走北风。","九域自此一，益见圣世崇。","大哉先帝仁，允矣丞相忠。","嗟我始弱冠，弗获拜此公。","作颂歌元勋，因之写吾衷。"]},{"t":"送文子方调选云南","f":"五言古诗","c":["我友文子方，其人美如玉。","高谈动卿相，惠利厚风俗。","文章多古意，清切绿水曲。","纷纷凫鹥群，见此摩霄鹄。","今当使西南，万里道邛蜀。","铨衡非细事，贤俊要甄录。","远人待子来，饥者望菽粟。","贤劳亦常事，但恐期程促。","马嘶晨当行，草长春正绿。","执手临路歧，使我空踯躅。"]},{"t":"吴真人卢沟雨别图","f":"五言古诗","c":["驱马上河梁，执手远别离。","远别数千里，临分各相思。","山川一何悠，去去勿复迟。","高堂有双亲，黄发映厖眉。","还家拜堂下，置酒作儿嬉。","却归见天子，忠孝两无亏。","人生如公少，致身贵及时。","此行将未巳，亲寿当期颐。"]},{"t":"高氏谨节堂","f":"五言古诗","c":["先圣有明训，见诸庶人章。","少小诵习之，白首不敢忘。","高子躬孝弟，养亲在高堂。","萧公三大字，岌岌端且庄。","对之铭座右，凛然肃冠裳。","谨身用始节，节用乃无荒。","斯言非虚语，旨远味自长。","守此期勿失，善积有馀庆。"]},{"t":"清胜池上偶成","f":"五言律诗","c":["竹色雨馀碧，蝉声风际清。","方池含绿水，中有纤鳞行。","浮沉各异态，亦足悦吾情。","欣赏方自兹，庶复得此生。"]},{"t":"重用韵","f":"五言律诗","c":["孤花色更媚，密竹气自清。","怀彼橘中乐，偶兹池上行。","荣华或伤性，赏静可怡情。","坐久不成起，待得月华生。"]},{"t":"赠韩定叟","f":"五言律诗","c":["萧萧晚雨细，淅淅幽丛响。","炉温动馀馥，研润生新赏。","方欣情话款，复此丘园想。","即事可忘忧，胡宁困尘鞅。"]},{"t":"次韵韩定叟留别","f":"五言古诗","c":["季冬寒气结，晨兴懔严霜。","越江不可涉，欲涉恨无梁。","飘飘客衣薄，烈烈北风凉。","会少别何多，令人心靡忘。","相去数百里，东西渺相望。","岂无琴与书，抚心独彷徨。","鬓毛各已苍，目视亦茫茫。","中年别亲友，作恶固其常。","安得传羽翼，与子俱飞翔。"]},{"t":"拟古","f":"五言古诗","c":["长夜何漫漫，寒鸡胡不鸣。","我行在中野，霜露上沾缨。","虎豹夹路啼，㷱罴复纵横。","我前鬼长啸，我后啼鼯鼪。","四顾寂无人，北斗高且明。","天道诚幽远，吾心空屏营。"]},{"t":"酬潘提举","f":"五言古诗","c":["卧病六十日，愦愦无一欣。","时取古书读，那复能知新。","客从辽东来，一见意自亲。","高谈极虚无，微言合道真。","远宦万里外，飘然绝埃尘。","归来如老鹤，笑视世间人。","胡为肯顾我，扁舟霅溪滨。","白发我巳老，青云子当伸。","京师人物囿，子往无逡巡。","而我慵墯久，栖迟甘隐沦。"]},{"t":"秋日言怀","f":"曲","c":["暑退草木苏，绿阴秋更繁。","玄蝉寂无声，蛬?巳复喧。","四序有代谢，人事何足言。","尘冠久不弹，散发坐前轩。","俛仰岁云莫，迟此负朝暄。"]},{"t":"送姚子敬教授绍兴","f":"五言古诗","c":["我友子姚子，风流如晋人。","白眼视四海，清言无一尘。","结交三十年，每见意自新。","皎皎白驹瘦，华发无缁磷。","此行度浙水，言采会稽芹。","会稽山水胜，王谢雅所欣。","亦有支许俦，迭递为主宾。","子往访遗迹，棹船镜湖滨。","狂客虽已去，高情自清真。","以子绝代才，数贤可比伦。","登山复临水，啸歌且怡神。","时时书寄我，用慰情相亲。"]},{"t":"述怀","f":"五言古诗","c":["我性真且率，不知恒怒嗔。","俯仰欲从俗，夏畦同苦辛。","以此甘弃置，筑屋龟溪滨。","西与长松友，东将脩竹邻。","桃李粗罗列，梅柳亦清新。","渐与市朝远，颇觉渔樵亲。","自谓独往意，白首无缁磷。","安知承嘉惠，再踏京华尘。","京华人所慕，宜富不宜贫。","严郑不可作，兹怀向谁陈。"]},{"t":"送李仲渊同知眉州","f":"五言古诗","c":["西风吹客衣，秋日明远树。","萧萧班马鸣，念子明当去。","人生贵适意，要津何必据。","佐州亦不恶，足展经济具。","峨眉山川秀，文俗盛如故。","喜子过我乐，增我羁旅虑。","匆匆万里别，益叹相见暮。","此心如天河，随子西南注。"]},{"t":"幽独二首 其一","f":"五言古诗","c":["闲居无与娱，幽独欣有得。","松翁善啸歌，花女美颜色。","人生亦何为，耳目皆幻适。","我今未半百，鬓发早巳白。","牙齿复动摇，行当为去客。","且尽须臾欢，忘言坐苔石。"]},{"t":"幽独二首 其二","f":"五言古诗","c":["独坐不自聊，披草寻微径。","夕阳在高林，篱落有馀映。","依依增远想，历历生晚德。","凉蝉轧鸣筝，候虫击清磬。","大小皆有从，雄雌各相应。","沉吟复踌躇，忽觉西山暝。"]},{"t":"允怀斋","f":"五言古诗","c":["小斋深且明，中有万卷书。","斋中古君子，寸田自耘锄。","人生万善具，政当复其初。","操存贵勿忘，道积乃有馀。","时复南荣下，静看云卷舒。"]},{"t":"送文章甫陕西都事","f":"五言律诗","c":["籍甚潞公孙，去为西省客。","矫矫国士风，婉婉幕中画。","泾渭寒有声，终华秋更碧。","聊因佐理馀，题诗寄来驿。"]},{"t":"美人隔秋水","f":"五言古诗","c":["美人隔秋水，只尺若千里。","可望不可言，相思何时巳。","庭树多落叶，日夕秋风起。","我今年已衰，素发拥两耳。","回思少年时，容颜若桃李。","美人何当来，一笑怀抱洗。","未见令我思，既见胡不喜。"]},{"t":"赠季明道尊师","f":"五言古诗","c":["我游皆意行，仙馆欣有遇。","麻衣皓如雪，蓬鬓飒以素。","悬知有道者，一见乃如故。","行当还山中，清飙送云驭。","苍松无凡声，石局有生路。","风雷坐可致，龙虎俨诃护。","空令尘中人，矫首企烟雾。"]},{"t":"云林山中 其一","f":"五言古诗","c":["松风太古声，欲写不可状。","仰观空翠滴，俯听潮音壮。","岂惟尘虑涤，亦觉神情王。","平生独往意，老矣天所放。","翳翳林竹间，山鸟时一唱。","俗氛虽云远，勿起清净障。"]},{"t":"云林山中 其二","f":"五言古诗","c":["九日当采菊，登高古相传。","我今值佳节，燕坐云林颠。","亦有岩间花，青蕊露华鲜。","采采服九英，饮水可长年。","况兹霜稻熟，刈我山下田。","一饱无复事，了我粥饭禅。"]},{"t":"题括苍山成德隐玄洞天","f":"五言古诗","c":["洞天在何许，乃近在人间。","神仙亦人耳，仙成厌尘寰。","冥冥隐玄洞，峨峨括苍山。","卿云时蓊勃，赤乌昔飞翻。","缅怀葛玄翁，一往不复还。","餐霞弄明月，解缨濯潺湲。","青芝伺时生，绿萝共谁攀。","服食去道远，孤坐亦非丹。","清歌极幼眇，朱书勒孱颜。","千年有白鹤，飞来启玄关。"]},{"t":"题先天观","f":"五言古诗","c":["对此山水咏，使人尘虑销。","况兹构真馆，燕坐远烦嚣。","青林荫户牖，素云冠山椒。","松风和涧泉，杂佩响琼瑶。","焚香玉女降，长斋百灵朝。","仙道本不远，清都亦非遥。","自嗟衰莫年，颇费猿鹤招。","安得生羽翰，从子以消摇。"]},{"t":"周南翁悠然阁","f":"五言律诗","c":["青山与高人，一见如有约。","悠然相莫逆，无语心自乐。","凌虚步丹梯，揽秀有高阁。","应同九皋鹤，翱翔在寥廓。"]},{"t":"夏日即事呈六兄","f":"五言古诗","c":["下帘却畏日，开轩纳清风。","虽无政事关，亦见好恶公。","此心如白璧，聊与世容容。","有兄远方来，一笑杯酒同。","我虽不解饮，预恐尊中空。","呼儿更往沽，勿使欢意穷。"]},{"t":"送谢伯琰","f":"五言古诗","c":["纂纂枣实繁，嘒嘒蝉声稠。","炎暑尚尔炽，西风犹未秋。","怜子触热行，不惮道里脩。","栈阁天下险，锦城西南陬。","过家因上冢，圣恩贲林丘。","鞍马虽驱驰，於义不可留。","子村瑚琏器，用世美且周。","明时方任贤，驿程难久游。","去去早言还，庶解离别忧。"]},{"t":"偶记旧诗一首","f":"五言律诗","c":["春情浩无端，野兴欣有瞩。","山光艳桃李，涧影写松竹。","古来岩穴士，白驹在空谷。","幽鸟何处来，啼破林烟绿。"]},{"t":"夏至","f":"五言律诗","c":["夏至午之半，一阴巳复生。","坚冰亦驯至，顾岂一朝成。","万物方茂悦，安知有彫零。","君子感其微，恸笑几失声。"]},{"t":"庭前松","f":"五言律诗","c":["手种庭前松，于今二十年。","清风时过之，我琴不须弦。","高标傲岁晚，秀色凝空烟。","有怀贞白君，世岂知其玄。"]},{"t":"閒居","f":"五言律诗","c":["荒庭芜弗治，翳翳草与筠。","池鱼出娱客，林鸟来依人。","閒居意自足，何者为戚欣。","况於黄卷间，时与圣贤亲。"]},{"t":"病中春寒","f":"五言古诗","c":["仲春尚寒气，林花无艳姿。","弊裘拥衰疾，风雨何凄其。","始雷发东隅，霁牖阳光披。","微风草际动，落英池面移。","幽禽变圆吭，游鱼扬细鬐。","我病自此愈，泛舟溪水湄。","小舆指南盖，短筇问东毗。","机心不复有，高蹈农与羲。"]},{"t":"松涧诗赠丁师善","f":"五言古诗","c":["青松上参天，下有幽涧泉。","高人居其閒，万虑不至前。","读书得妙趣，视世等浮烟。","胡为舍此去，杖策走日边。","要当陈忠益，民瘼会有痊。","却归弄泉石，静听松风眠。"]},{"t":"兴中府某氏见山楼","f":"五言古诗","c":["东北有高楼，迢递数十尺。","朝霞映窗牖，浮云来凡席。","莽苍一望间，崒嵂千峰碧。","青山何处无，所见多迫迮。","伟哉医无闾，周礼载简册。","我虽身未到，心想已可索。","但惜道里赊，处地远且僻。","嘉彼楼居子，不受世故役。","爱山如爱客，相对乐晨夕。","应笑平地人，尘埃坐充斥。"]},{"t":"赠恢上人","f":"五言律诗","c":["晨坐古松下，有僧来叩扉。","松花落金粉，细细点春衣。","折松当麈尾，相对澹忘机。","汤休不可作，政索解人稀。"]},{"t":"露坐","f":"五言律诗","c":["露坐夜将半，澹然无所为。","草根虫鸣歇，松梢萤度迟。","城市多尘杂，令人心不怡。","兹丘亦可老，巳与白云期。"]},{"t":"题黄华为其父写真","f":"五言律诗","c":["仙人紫霞衣，危坐古松间。","玉色映流水，不动如丘山。","平生黄华老，得意每相关。","九原如可作，与君相对闲。"]},{"t":"题先贤张公十咏图","f":"五言古诗","c":["吴兴潇洒郡，自古富人物。","溪山映亭榭，尊俎照华发。","当时盍簪地，蓁莽久芜没。","空馀诗语工，不共芳草歇。","抚卷想胜风，冠佩其敢忽。","先民不可见，惆怅至明发。"]},{"t":"犀浦遐观诗","f":"五言古诗","c":["男子四方志，蜀都天下奇。","李侯并门豪，杖节镇坤维。","爱此雪山雄，卜宅屖浦湄。","锦城既云乐，焉用还家为。","遗像开生面，清风凛英姿。","应同武侯庙，人怀千古思。"]},{"t":"吴俊卿义塾","f":"五言古诗","c":["礼义生富足，为富或不仁。","谁能如吴君，捐己以惠人。","开塾延师儒，聚书教比邻。","岂徒名誉美，要使风俗淳。","人物方眇然，作养当及辰。","文章虽致身，经术乃新民。","宣公相业著，辅子理学醇。","二贤乡先正，千载德不泯。","吴君真盛举，勉哉继前尘。","何当袭春服，从子语水滨。"]},{"t":"寄题杜尊师白云庵琼秀亭 其一","f":"五言古诗","c":["白云从何来，乃在计筹山。","山中古仙伯，翱翔白云间。","城市多嚣尘，山林幽且闲。","结屋松竹里，开窗泉石边。","清斋诵道德，焚香降神仙。","俯仰皆自得，洗心游泰玄。","税驾往从之，规买山下田。","蓺药扫白发，栽桃映红颜。","庶几林下意，期了区中缘。","丹成从师去，笑拍洪崖肩。"]},{"t":"寄题杜尊师白云庵琼秀亭 其二","f":"五言古诗","c":["琼山发天秀，珠泉表地灵。","柔荑吐丹葩，乔林标绛英。","酌醴吸冲和，汲涧漱甘清。","石门开洞府，木龙走岩扃。","清飙一时至，四座浮幽馨。","阆风何必远，世尘空自冥。","从游当有期，淹留讵无成。","左手撷紫芝，右手采黄菁。","振衣陟崇冈，遐观散神情。","长啸烟雾里，满空鸾鹤声。"]},{"t":"杨坚州治水歌","f":"楚辞体","c":["秋水至兮大河溢。","金堤决兮流漂疾。","田畴泊兮为民忧。","鱼鳖肆兮地上游。","谁能治水兮徵阳侯。","具畚锸兮万人聚。","势悍急兮不可以禦。","问河伯兮何所怒。","岁不登兮民且寠。","侯精诚兮感神明。","赤蛇蜿蜒兮昭瘚灵。","奠桂酒兮荐芳馨。","神攸歆兮堤防成。","水复故道兮民载宁。","天子圣兮地道平。","万岁千秋兮扬颂声。"]},{"t":"兵部听事前枯柏","f":"七言古诗","c":["庭前枯柏生意尽，枝叶乾焦根本病。","黄风白日吹沙尘，鼓动哀音乱人听。","嗟哉尔有岁寒姿，受命於地独也正。","雨露虽濡心自苦，凤鸟不来谁与盛。","岂无松槚在山阿，只有蓬蒿没人胫。","我生愧乏梁栋才，浪逐时贤缪从政。","清晨骑马到官舍，长日苦饥食还并。","簿书幸简不得休，坐对枯槎引孤兴。","人生何为贵适意，树木托根防失性。","几时归去卧云林，万壑松风韵笙磬。"]},{"t":"题二乔图","f":"七言律诗","c":["长江东来水滔滔，谁谓江广不容刀。","中有乔家女儿泪，何意师昏随二豪。","龙虎方争欲相啖，鸾鸟铩翮将安逃。","不见当时老诸葛，独聘丑妇何其高。"]},{"t":"题黄素黄庭后此书飘飘有仙气意其为扬许旧迹盖人间至宝伯几所藏也","f":"七言古诗","c":["琴心玉文洞玄玄，金钮朱锦乃汝传。","子能得之可长年，黄素缜㮚完且坚。","横理如发约两边，从有赤道如朱弦。","文居其间走玄蛾，飞云卷舒相终始。","大道甚夷非力使，无为自然有至理。","谁能精专换骨髓，扫除俗尘不瑕秽。","目中有神乃识真，白玉为轵装车轮。","裹以天上翠织成，仙人楼居俨长生。","鸾鹤翔舞猿猱轻，子能宝之慎勿惊，宫室之中夜自明。","上清真人扬与许，焚香清斋接神女。","手作此书留下土，千年流传子为主。","东方苍龙右白虎，廉不子求贪不与。"]},{"t":"赠相士","f":"七言古诗","c":["我昔放浪江湖间，举头开眼看青山。","安知世故不相舍，坐受尘土凋朱颜。","髭须巳黄行且白，亦知人生不满百。","功名富贵非我事，但愿有酒呼好客。","钱唐江边逢少年，两眼善相口谈天。","封侯食肉骨法异，慎勿置我诸公前。","江南春暖水生烟，何日投闲苕水边。","买经相牛亦不恶，还与老农治废田。"]},{"t":"送朱仲阳太平教授","f":"七言律诗","c":["列仙之儒山泽臞，手中黄纸新除书。","教官虽冷实清选，当涂山川如画图。","我生无能百不如，盍不从君赋归与。","请君为我酹大白，矫首南望心烦纡。"]},{"t":"题李公略所藏高彦敬夜山图","f":"七言律诗","c":["高侯胸中有秋月，能照山川尽豪发。","戏拈小笔写微茫，只尺分明见吴越。","楼中美人列仙臞，爱之自言天下无。","西窗暗雨政愁绝，灯前还展夜山图。"]},{"t":"赠吴真人","f":"七言古诗","c":["上清真人天上来，云收雾敛天门开。","手持玺书归故里，琼琚玉佩相追陪。","堂上老仙千岁寿，喜儿归来酌春酒。","帝命建尔于上公，老仙拜前儿拜后。","古来子贵父母荣，今见恩荣萃一门。","紫衣玉带照华发，金冠瑶简明朝暾。","人间五福谁能备，岁晚寒香满天地。","真人妙行我所知，曾是玉皇香案吏。"]},{"t":"题也先帖木儿开府宅壁画山水歌","f":"七言古诗","c":["大山崒嵂摩青天，小山平远通云烟。","商侯胸中有丘壑，信手落笔分清妍。","阆风玄圃元不远，粲烂金碧流潺湲。","参差涧谷楼观起，萦纡石路朱桥连。","松风飕飗响虚阁，棋声剥琢来群仙。","渔歌樵唱渺何许，纶巾羽扇清溪边。","高情自有泉石趣，凉意不受尘埃缠。","世间书画亦岂少，谁能真赏如公贤。","华堂风日不到处，绝胜绣幕空高悬。","举觞酌酒为公寿，眼明对此三千年。"]},{"t":"孤燕曲","f":"曲","c":["燕燕复燕燕，孤飞不忍见。","故雄巳作长别离，孀雌守节令人羡。","昔日双双拂烟草，十年独宿梁间藻。","叹息人间贞妇少，人独何心不如鸟。"]},{"t":"李氏种德斋诗","f":"曲","c":["一年之计种谷，十年之计种木。","百年种德知何事，插架鳞鳞书满屋。","世人责报嗟何速，我自无心徼后福。","日中为市百贾闹，竞逐锥刀蛾赴烛。","鬻书之利虽云薄，要令举世沾膏馥。","为贤为智皆由此，耕也未必能干禄。","他年种德看成功，远在子孙应可卜。"]},{"t":"赠张彦古","f":"七言古诗","c":["秋雨新巳风日清，匆闻剥啄紫门声。","出逢麻衣老仙伯，身长七尺双瞳明。","平生学道几半世，一见洒洒心为倾。","大道无为返尔朴，自然有路通长生。","我今素发飒以白，宦途久矣思归耕。","吴兴山水况清绝，白云满岭堪怡情。","老仙何当从我去，小筑茅屋依峥嵘。","还丹已就蓬岛近，笑指尘海寻方平。"]},{"t":"送田师孟知河中府","f":"七言律诗","c":["汉二千石入为相，邑令或入为三公。","圣朝用人亦复尔，予以此贺田河中。","田侯年少与子友，今三十年俱白首。","离觞未尽去马鸣，愁向风前折杨柳。"]},{"t":"赵克敬耘庵","f":"七言古诗","c":["赵子居室名耘庵，不以雨旸为旱潦。","寸田尺宅勤自治，稂莠芟夷嘉谷好。","平生万事无助长，岁晚所收皆至宝。","我托官联几一载，怀抱於人每倾倒。","交情雅有古淡风，此意难为轻薄道。","况我同姓古所敦，百世可知宜细考。","三十年来如一梦，白发相看今尽老。","我方告归理墓田，莫怪赋诗殊草草。"]},{"t":"赠捏古伯","f":"七言律诗","c":["有僧有僧住江心，以色杀人凶且淫。","贪官若吏私其金，灭迹钜海无由寻。","安知冤魂痛不释，群然号诉众所觌。","尽诛凶俦冤始白，谁其白之捏古伯。"]},{"t":"送高郎仲德往汝州迎母","f":"七言古诗","c":["高郎八岁失其母，每一言之泪如雨。","忽然有信自北来，知道慈亲在临汝。","艰难一别四十年，惊喜失声浑欲舞。","水行有舟陆有车，襆被即行身欲羽。","遥想团栾再拜时，膝下抱持喧笑语。","人生天地谁无母，此别真如隔今古。","焉知孝感动神明，万里言归复相睹。","吴兴山水清且远，指日安舆还乐土。","我当理舟楫迎汝，买红缠酒刲肥羜。","斑衣喜色映庭萱，白发从教老农圃。"]},{"t":"次韵叶公右丞纪梦","f":"七言古诗","c":["倦游客子何时去，屡欲言归天未许。","故乡乐事时上心，破浪长鱼日登俎。","一蓑一笠得自由，某水某丘犹可数。","前年有诏举逸民，一旦驰驿登天府。","岂知佐理自有才，勉强尽瘁终无补。","青春憔悴过花鸟，白日勾稽困文簿。","栖栖颜汗逐英俊，往往笑谈来讪侮。","倦㒒思归语见侵，瘦马长饥骨相拄。","天生我公出瑞世，辅相明时期复古。","好将图画上凌烟，未遂衣冠挂神武。","髭须半白称貂蝉，步履渐轻宜印组。","道长自觉小人消，乱沮政须君子怒。","得闲有兆天与祥，吉梦初回月当户。","因公此意乞归田，不辞歌诗为公舞。"]},{"t":"杨天瑞府判平冤诗","f":"七言古诗","c":["至元年间岁辛卯，建宁总管有马谋。","间因盗起建阳县，欲引镇军肆诛屠。","闻民张氏有女子，小名月娘美且姝。","思得此女恣淫泆，乃诬张氏与贼俱。","月娘逃匿不可得，旁及邻女遭奸污。","既得月娘欲灭口，父母亲戚皆囚俘。","一家九人一时毙，痛入骨髓天难呼。","其馀五人亦濒死，身被榜掠无完肤。","人家不幸产尤物，破家灭族真无辜。","杨侯天瑞为府判，深疑此事皆虚诞。","奋髯仗义以死争，力谓马谋当并按。","月娘得脱为良人，待尽残囚出狱犴。","沉冤极枉一旦伸，台省交章同论荐。","圣神天子甚明察，诏下天门发英断。","马谋竟以罪伏诛，行路闻之亦咨叹。","邑人为侯生立祠，牲酒缤纷勤荐祼。","杨侯平反世希有，宜有升迁示旌劝。","政事固因才德美，岁月难将资品算。","即今巳过二十年，那抛朱绂换青衫。","皋夔在位方进贤，请为诵我平冤萹。"]},{"t":"题舜举摹伯时二马图","f":"七言古诗","c":["二龙何时飞上天，空有骏影人间传。","一匹凤头来于阗，一匹赐名花满川。","李侯作画述者钱，想见温公当国年。","太平时节巡游少，立仗归来饱春草。","老向天闲无战功，马自不逢人皞皞。"]},{"t":"赠相师王蒙泉","f":"七言古诗","c":["王君善相多奇中，说好誇奇无刺风。","巳将幻化等虚空，问寿几何持底用。","遭时乏才偶致位，处非其宜常自讼。","词林每愧文字拙，玉带却怜腰胯重。","身归闾里困衰疾，心恋阙庭形夜梦。","端如老骥欹欲倒，骏骨虽存难受鞚。","清溪如玉绕屋庐，个个渔舟时看弄。","且将闲散乐馀生，岂望残年给残俸。"]},{"t":"雪后同子俊游何山次韵四首 其一","f":"五言律诗","c":["同是清閒客，俱为放浪游。","晴山依雪壮，野水带冰流。","风急松杉乱，年登荠麦收。","生涯虽未老，吾欲觅菟裘。"]},{"t":"雪后同子俊游何山次韵四首 其二","f":"五言律诗","c":["步履行危磴，凭阑得妙峰。","鸟飞迷故道，人去想遗踪。","掩冉风前竹，支离涧底松。","山僧饭不足，不是忘鸣钟。"]},{"t":"重游弁山 其一","f":"五言律诗","c":["出郭闻莺语，穿林散马蹄。","涧松何郁郁，春草又萋萋。","白石那堪煮，丹厓倘可梯。","平生爱高兴，只合此幽栖。"]},{"t":"秋夜","f":"五言律诗","c":["草蔓行多露，虫声报早秋。","明河斜未转，大火巳西流。","欲作传杯饮，谁能秉烛游。","清晨拂鞍马，适野拟消忧。"]},{"t":"独夜","f":"五言律诗","c":["生事怜吾拙，怀人阻道脩。","角声悲静夜，灯影伴幽忧。","水落红衣老，天寒翠袖愁。","云中有过雁，哀叫亦何求。"]},{"t":"闻角","f":"五言律诗","c":["吹角秋风里，边声入莫云。","抑扬如自诉，哀怨不堪闻。","老马行知道，孤鸿飞念群。","秪今霸陵尉，那识旧将军。"]},{"t":"次韵冯伯田秋兴 其一","f":"五言律诗","c":["摇落故园秋，溪山处处幽。","无钱频贳酒，多病倦登楼。","文采陶彭泽，丹青顾虎头。","谁能混流俗，浩荡一浮沤。"]},{"t":"本斋先生挽诗 其一","f":"五言律诗","c":["昔我先君子，交游半老儒。","词林宗匠在，制阃辅臣须。","晚节风尘际，闲居岁月徂。","谬称诗赋善，深痛典刑无。"]},{"t":"本斋先生挽诗 其二","f":"五言律诗","c":["德邵龟龄迈，神全鹤发春。","管宁安皂帽，龚胜谢蒲轮。","小楷名空在，遗言意更亲。","平生知己恨，泪落霅溪滨。"]},{"t":"赠权季玉兼简李顺甫","f":"五言律诗","c":["幕府文书静，湖山春事多。","风烟归逸兴，花鸟助高歌。","自愧诸生后，其如二妙何。","卜邻应有日，退食数相过。"]},{"t":"送杨幼澄教授归江西兼寄吴幼清","f":"五言律诗","c":["客里相从久，愁中欲别难。","此行登仕版，未觉负儒冠。","北度怜江总，东归忆幼安。","著书应满屋，妙处共谁看。"]},{"t":"送李清甫由御史出按四川","f":"五言律诗","c":["蜀道青天上，绣衣骢马行。","霜威御史府，春色锦官城。","万里平反报，三年菽水情。","相逢一杯酒，似为别离倾。"]},{"t":"送刘伯常淮东都事","f":"五言律诗","c":["久客倦游甚，思归劳寸心。","之子复南迈，欲别惜光阴。","萧条楚山远，渺瀰淮水深。","梦中不可到，何用解愁襟。"]},{"t":"晋公子奔狄图邀端父御史同赋","f":"五言律诗","c":["杌隉居蒲日，艰难奔狄时。","天方兴伯者，数子实从之。","岁久丹青暗，人贤简册悲。","至今绵上路，犹忆介之推。"]},{"t":"题米元晖山水","f":"五言律诗","c":["卧游渺万里，楚天清晓秋。","初日江上出，白云山际浮。","莽苍迷烟树，隐约见孤舟。","丹青不可作，思子徒离忧。"]},{"t":"送张仲实还杭州","f":"五言律诗","c":["张子早英发，哦诗遗垢氛。","瘦骨映秋水，青眼视晴云。","黄公酒垆侧，王令为书裙。","相望苦不远，何用惜离分。"]},{"t":"食粥","f":"五言律诗","c":["杲杲西流日，㴞㴞东逝波。","春光蓟丘晚，柳色上林多。","不道含香贱，其如食粥何。","明时无小补，郎署谩蹉跎。"]},{"t":"酬卫处士见赠","f":"五言律诗","c":["之子有道气，山居诗兴多。","琴清鹤自舞，林静鸟能歌。","未遂携家隐，深惭辍棹过。","他年从杖屦，养寿向岩阿。"]},{"t":"送吴礼部奉旨诣彭湖","f":"五言律诗","c":["为国建长策，此行非偶然。","止戈方见武，入海不求仙。","朱绂为郎日，金符出使年。","早归承圣渥，图像上凌烟。"]},{"t":"大司农侯公挽诗","f":"五言律诗","c":["理学推高第，清朝位列卿。","政声先日著，经术莫年精。","乍识俄离逖，方闲遽陨倾。","重为天下惜，涕泪落纵横。"]},{"t":"和周景远见寄二首 其二","f":"五言律诗","c":["止酒陶彭泽，能书王右军。","逃禅宁辟俗，感旧惜离群。","泽国茫茫水，霜空黯黯云。","为农投老去，北望隐思君。"]},{"t":"奉隆福召命赴都过德清别业","f":"五言律诗","c":["骤喧气候变，幽园卉物凄。","山云石上起，春鸟雨中啼。","牵衣怜稚子，举案愧山妻。","苦被虚名累，未得遂高栖。"]},{"t":"谢石林赠湖石次其韵","f":"五言律诗","c":["怪石曾听法，来从不二门。","玲珑浮磬韵，斑驳古苔痕。","池月岩边上，春云水面屯。","微尔能辍赠，此意向谁论。"]},{"t":"胡穆仲先生挽诗","f":"五言律诗","c":["我有三益友，对之如古人。","布衣甘陋巷，书册老遗民。","泪落黔娄被，神伤郭泰巾。","请为千字诔，书刻上坚珉。"]},{"t":"赠永清曹显祖县尹","f":"五言律诗","c":["赤县郎官宰，清朝学士班。","云端双履去，花底一琴间。","鸿鹄宜天路，骐驎近帝闲。","会当从此召，岂待及瓜还。"]},{"t":"赠郑之侨","f":"五言律诗","c":["我有故人子，少年能缀文。","偏工吟九日，已解赋齐云。","落落驹千里，昂昂鹤出群。","却怜吾老矣，须鬓白纷纷。"]},{"t":"来鹤亭","f":"五言律诗","c":["客游真馆日，鹤来玄圃时。","援笔二大字，欣然千载期。","长鸣松月照，屡舞竹风吹。","天路何寥廓，吾与尔同之。"]},{"t":"李太白酒楼","f":"五言律诗","c":["城迥当平野，楼高属莫阴。","谪仙何俊逸，此地昔登临。","慷慨空怀古，徘徊独赏心。","峄山明望眼，百里见遥岑。"]},{"t":"题赵敬父侍御祖德诗","f":"五言律诗","c":["弃子抱兄子，古来闻邓攸。","贤哉赵氏母，盛德迈前脩。","阴骘理须复，高门庆自流。","诜诜庭下玉，簪笏尽公侯。"]},{"t":"赠刘节轩侍御","f":"五言律诗","c":["骢马人皆避，沙鸥意独閒。","天恩沾赠典，泉壤慰慈颜。","乐在箪瓢外，春生杖屦间。","闻閒且行乐，但恐趣朝班。"]},{"t":"寄题陆振之与閒堂","f":"五言律诗","c":["一閒天所与，万事世从疏。","名教有乐地，安心为广居。","林间听啼鸟，濠上看游鱼。","意适无馀想，时还读我书。"]},{"t":"次韵观复表兄见简 其一","f":"五言律诗","c":["寒雨何时已，停云不肯开。","难陪山简醉，空忆谪仙才。","梅蕊枝枝发，幽禽日日来。","可能无过我，真复要诗催。"]},{"t":"故两浙运使李公挽诗 其一","f":"五言律诗","c":["昔我閒居日，公来作守时。","敝庐曾寓止，暇日每娱嬉。","篆籀传书法，弦歌送酒卮。","情亲自兹始，岁晚辱深知。"]},{"t":"故两浙运使李公挽诗 其二","f":"五言律诗","c":["白发仪刑老，清朝侍从班。","理财羞聚敛，治郡已恫瘝。","卧疾留南久，招䰟竟北还。","向来漳水道，泪落郭西山。"]},{"t":"送张梦符郎中还朝","f":"五言古诗","c":["侍从班行近，咨谋出使频。","乘轺山水国，把酒浙江春。","骢马歌仍在，祥麟德自驯。","大书诚有法，妙句不无神。","爱士容疏放，忘年接隐沦。","回辕瞻斗极，听履上星辰。","此别真堪惜，兹情未易陈。","数公如见问，为说混风尘。"]},{"t":"秋日即事","f":"五言古诗","c":["今日秋色好，天高景不暄。","清飙动林薄，凉意满丘樊。","俗客无因至，幽禽时自言。","露浓金盏侧，香远玉簪繁。","谁办东山妓，空馀北海尊。","莫吟招隐赋，桂树可攀援。"]},{"t":"元日朝贺","f":"五言古诗","c":["阊阖曙光生，觚棱瑞霭横。","治朝春有象，严跸物无声。","簪笏千官列，箫韶九奏成。","彤墀簇仙伏，翠树拂霓旌。","绝域梯航至，来庭玉帛盈。","皇图天远大，圣德日高明。","兵息知仁布，民熙见化行。","耄倪齐鼓舞，率土共升平。"]},{"t":"奉赠平章李相公十韵","f":"五言古诗","c":["鱼水千年庆，龙云亿载春。","乾元开泰运，圣主得贤臣。","画像丹青炳，书题刻画真。","春宫承宠旧，秋谷赐名新。","扶日登皇极，经邦赞化钧。","甘盘基相业，傅说应星辰。","报国非私已，逢时岂爱身。","谁能动天子，今复见山人。","始白诗书效，行看俗化淳。","硕陈归美意，作诵比丞民。"]},{"t":"次韵子俊","f":"七言律诗","c":["岁云莫矣役车休，蟋蟀在堂增客愁。","少年风月悲清夜，故国山川入素秋。","佳菊巳开催节物，扁舟欲买访林丘。","从今放浪形骸外，何处人间有悔尤。"]},{"t":"次韵本斋先生即事","f":"七言律诗","c":["重揽衣裘敝更宽，徂年欲莫气先寒。","雨中百草难为绿，霜后黄花尚耐看。","千古清真耆旧传，半生辛苦腐儒冠。","便应筑室山阿去，嘉与斯人赋考槃。"]},{"t":"次韵帅初","f":"七言律诗","c":["吴越相望三十年，相逢意气共翩翩。","长歌白石徒为尔，远访丹砂亦偶然。","海气昏昏云拂地，江风飒飒雨连天。","他时别后相思处，欲问山阴雪后船。"]},{"t":"送李元让赴行台治书侍御史","f":"七言律诗","c":["郎署联班仅一秋，旦同趍省莫同休。","岂惟官事奔忙共，自觉吾侪气味投。","骢马只今登宪府，白鸥何日傍沧洲。","别离不似今朝恶，南望令人生白头。"]},{"t":"送刘天锡镇守鄂州","f":"七言律诗","c":["将军好武更敦书，执戟多年卫帝居。","扈跸惯骑天育马，分符真食武昌鱼。","弓刀行色寒逾壮，尊酒风流澹有馀。","江路梅花政堪折，未应便向故人疏。"]},{"t":"送阎子静廉访浙西","f":"七言律诗","c":["翰林禁近逼青冥，宪节乘骢出帝城。","海内文章归浑厚，浙西民物望澄清。","姑苏落日荷花净，震泽秋风橘柚明。","忆向玉阶承圣语，早归黄阁慰苍生。"]},{"t":"送孟君复信州总管","f":"七言律诗","c":["君侯弱冠已专城，未许甘终浪得名。","五马人生真足贵，一毫宠辱不须惊。","暮云去作江东梦，秋雨无忘蓟北情。","歌罢风前折杨柳，离觞那忍为君倾。"]},{"t":"追挽宋汉臣副使","f":"七言律诗","c":["生世怜余后此公，闻人说似涕无从。","一时文献交游里，十载烟霞杖屦中。","有子能为先友记，临终方见古人风。","秋漪亭上残阳色，犹照先生醉后容。"]},{"t":"钦颂世祖皇帝圣德诗","f":"七言律诗","c":["东海西山壮帝居，南船北马聚皇都。","一时人物从天降，万里车书自古无。","秦汉纵强多霸略，晋唐虽美乏雄图。","经天纬地规模远，代代神孙仰圣谟。"]},{"t":"李仲渊求其弟叔行万竹亭诗为赋一首","f":"七言律诗","c":["闻君有弟多栽竹，邀我题诗寄远情。","翠碧飞来人政静，凤凰鸣集实初成。","江波倒影春云合，山月笼阴夜气清。","我亦有亭深竹里，也思归去听秋声。"]},{"t":"王氏节妇","f":"七言律诗","c":["夫妇人伦之大者，夫死宁容有二天。","矧是簪缨闲姆训，故应诗礼得家传。","何须断耳徒惊俗，只是持身巳自贤。","年少寡居今白发，为君重赋柏舟萹。"]},{"t":"赵子敬御史志养堂","f":"七言律诗","c":["志养堂前骢马归，融融喜气动庭闱。","能令将种为书种，可是斑衣胜绣衣。","手树丛萱侵雪色，心同寸草报春晖。","不须更上陈情表，寿母康强世所稀。"]},{"t":"初到济南","f":"七言律诗","c":["自笑平生少宦情，龙钟四十二专城。","青山历历空怀古，流水泠泠尽著名。","官府簿书何日了，田园归计有时成。","道逢黄发惊相问，只恐斯人是伏生。"]},{"t":"春日送廉访监司赴都","f":"七言律诗","c":["春回北斗转招摇，使节迎春上九霄。","官道柔杨有生意，私田细麦长新苗。","东风河水冰初泮，迟日沙堤雪易销。","入觐彤廷元会毕，衮衣留相圣明朝。"]},{"t":"送刘安道指挥副使还都兼寄李士弘学士","f":"七言律诗","c":["昔来雨雪正霏霏，今去春鸿向北飞。","王事便应歌杕杜，家人未用叹蛜蝛。","据鞍横槊军威壮，把酒论文雅志违。","为问瀛洲李学士，相思何故信音稀。"]},{"t":"惊秋","f":"七言律诗","c":["泽国西风一夜生，故园乔木动秋声。","山川满目悲摇落，物色无心得老成。","下坂牛羊知故道，亲人鱼鸟近幽情。","向来豪气消磨尽，空对年光浪自惊。"]},{"t":"和邓善之九月雪","f":"七言律诗","c":["季秋惊见燕山雪，远客淹留愁病身。","憔悴自伤黄菊晚，横斜空忆野梅春。","苍松翠柏争擎重，绀殿红楼迥绝尘。","想得江南犹未冷，嫩橙清酒政尝新。"]},{"t":"次韵子敬怀王子庆往吴中","f":"七言律诗","c":["阖闾城郭填姑苏，吊古登台百感俱。","秋水远随鸿影没，江云长傍客帆孤。","吴时花草于今在，晋代风流绝世无。","别后故人须有得，已应怀宝问归途。"]},{"t":"次韵西云长老赠周仲和","f":"七言律诗","c":["江南春水碧於天，白鸟沧洲兴渺然。","刺绣可能如倚市，力田终不似逢年。","几因莼菜怀张翰，欲把丹砂访稚川。","才力如君强健在，不妨沽酒醉花前。"]},{"t":"送萧万户镇阆州","f":"七言律诗","c":["锦屏山下蜀江清，阆州城南春意生。","投壶今见诗书帅，树羽遥怜鼓角营。","远戍固须烦将略，杂耕因足见民情。","梅花到日应如雪，折取繁枝一寄声。"]},{"t":"留别沈王","f":"七言律诗","c":["珍重王门晚受知，一年长恨曳裾迟。","分瓯共酌人参饮，绕径同看芍药枝。","华屋焚香凝燕寝，画屏摘句写乌丝。","吴船万里东南去，采尽蘋花有所思。"]},{"t":"德昌总管雪后见过而余适往德清别业归来承惠诗走笔奉和","f":"七言律诗","c":["年过五十已无闻，老子犹容醉吐茵。","短棹冲寒投别墅，朱轓行雪布阳春。","诗成自可追群玉，笔冻真成秃万㕙。","且喜丰年多美酒，传杯慎勿厌□巡。"]},{"t":"三日后再雪德昌复枉骑见过既而复和前萹见赠辄亦次韵","f":"七言律诗","c":["夜深万籁寂无闻，晓看平阶展素茵。","茗椀纵寒终有韵，梅花虽冷自知春。","使君磊落如天骥，老我堆豗似冻㕙。","深愧闭门高卧客，枉劳车骑巳三巡。"]},{"t":"已酉元日朝拜喜晴总管次前韵见教复和一首","f":"七言律诗","c":["公庭拜罢笑声闻，晓色曈曈射锦茵。","元日不阴占乐岁，太平有象兆新春。","不知何地来银瓮，复报诸方致白㕙。","四海治安封禅举，岱宗久已望东巡。"]},{"t":"游乌镇次韵千濑长老","f":"七言律诗","c":["泽国人烟一聚间，时看华屋出林端。","巳寻竹院心源净，更上松楼眼界宽。","千古不磨唯佛法，百年多病只儒冠。","相逢已定诗盟了，他日重寻想未寒。"]},{"t":"赠张进中笔生","f":"七言律诗","c":["平生翰墨空馀习，喜见张生缚鼠毫。","韩子未容誇兔颖，涪翁底用赋猩毛。","黑头便有中书意，黄纸宁辞署字劳。","千古无人继羲献，世间笔冢为谁高。"]},{"t":"挽洞霄章耕隐","f":"七言律诗","c":["黄发萧萧瘦骨清，每於谈妙见高情。","琼浆政欲分丹鼎，霞佩胡为返赤城。","白鹤归来华表在，碧桃开尽玉棺成。","师今此去哀难悼，万壑松风共此声。"]},{"t":"次韵庞夷简礼部","f":"七言律诗","c":["故山深处桂阴浓，云碓无人水自舂。","玉友一尊为老伴，木奴千树当侯封。","宦途坎壈谋身拙，病骨支离触事慵。","早挂一帆归去好，五湖烟㬌最情钟。"]},{"t":"卢彦威用韵见赠亦复次韵","f":"七言律诗","c":["东篱紫菊露方浓，西舍黄粱夜自舂。","蕙帐夜空玄鹤怨，松门无锁白云封。","图书老去心犹在，朝市重来意转慵。","岂有高情齐隐逸，政缘多病巳龙钟。"]},{"t":"论书","f":"七言律诗","c":["右军潇洒更清真，落笔奔腾思入神。","裹鲊若能长住世，子鸾未必可惊人。","苍藤古木千年意，野草闲花几日春。","书法不传今已久，楮君毛颖向谁陈。"]},{"t":"寄题保定杜处士晚翠楼","f":"七言律诗","c":["楼外山光翠不如，楼中美人老耽书。","一尊绿酒刘伶醉，几点黄华陶令居。","虚旷自疑风月近，孤高应与世尘疏。","他时若到丹梯上，当有清谈一起予。"]},{"t":"赠张德玉","f":"七言律诗","c":["张君说易万人誇，幽赞神明断不差。","动静六爻虽有象，吉凶万变本无涯。","河图妙在纵横用，皇极曾传一倍加。","自笑已无疑可卜，有疑来问尔西家。"]},{"t":"岁晚偶成","f":"七言律诗","c":["致君泽物巳无由，梦想田园霅水头。","老子难同非子传，齐人终困楚人咻。","濯缨久判随渔父，束带宁堪见督邮。","准拟新年弃官去，百无拘系似沙鸥。"]},{"t":"次韵杜浩卿咏所藏研","f":"七言律诗","c":["我生老研日相寻，手不能神谩苦心。","墨妙巳无王令帖，诗穷空学杜陵吟。","质温未逊连城璧，气润先知几日霖。","只有子西知钝体，便应刻此当铭箴。"]},{"t":"送史总管廉访江东","f":"七言律诗","c":["历下方誇汉吏循，江东又见绣衣新。","可能召父专前代，更有萧规俾后人。","佐理非才常自愧，别离作恶向谁陈。","何当揽辔从公去，归泛清溪采白蘋。"]},{"t":"寿平章李韩公","f":"七言律诗","c":["瑞钟光岳应时需，日上天衢手自扶。","八表同风开寿域，五云异彩映台符。","经纶至治归贤相，陶冶斯文属大儒。","为国白头身未老，掌中行见有明珠。"]},{"t":"鹤归亭","f":"七言律诗","c":["仙去人间有故亭，四山林竹郁青青。","隐居真诰传千古，玉局丹文役万灵。","白鹤归来人换世，黄云翔集夜充庭。","步虚声转松风响，思掬岩泉洗耳听。"]},{"t":"挽道士危功远","f":"七言律诗","c":["处世纷纷一梦同，觉来虚室已成空。","药垆丹灶尘埃里，羽节琼轮杳霭中。","素壁尚明秋馆月，青松犹引夜窗风。","仙家自有逍遥趣，不用悲哀哭断蓬。"]},{"t":"送柳汤佐怀孟总管","f":"七言律诗","c":["河山王屋翠岧峣，玉辇曾临号乐郊。","老子分符称太守，诸儿骑竹候前茅。","春苗秋实供厨传，紫笋朱樱入贡包。","手种成阴千树柳，政成应有凤来巢。"]},{"t":"送吴真人谒告归为二亲八十之寿兼降香名山","f":"七言律诗","c":["许迈杨羲奕世仙，木公金母共长年。","斑衣归戏鄱君侧，绛节朝辞玉帝前。","去去青牛随紫气，飞飞白鹤绕香烟。","大椿自得人间寿，八十从今数八千。"]},{"t":"题高彦敬树石图","f":"五言绝句","c":["乔林动秋风，索索叶自语。","堂堂侍郎公，高怀政如许。"]},{"t":"题米元晖山水","f":"五言绝句","c":["澄江漾旭日，青嶂拥晴云。","孤舟彼谁子，应得离人群。"]},{"t":"题孙安之松楸图","f":"五言绝句","c":["坟墓在万里，宦游今五年。","人谁无父母，掩卷一潜然。"]},{"t":"题太白酒船图 其一","f":"五言绝句","c":["载酒向何处，稽山镜水边。","若为无贺老，兴尽便回船。"]},{"t":"因禅师挽诗 其一","f":"五言绝句","c":["先子同年友，唯馀此老存。","安心得禅悦，闭户道弥尊。"]},{"t":"因禅师挽诗 其二","f":"五言绝句","c":["面帝陈三语，还山又几春。","萧然无世累，卓尔出埃尘。"]},{"t":"因禅师挽诗 其三","f":"五言绝句","c":["朱阁非新构，青松只旧林。","佛澄今巳逝，无复听铃音。"]},{"t":"因禅师挽诗 其四","f":"五言绝句","c":["佛性无来去，群生自尔悲。","达观应大笑，政足见渠痴。"]},{"t":"因禅师挽诗 其五","f":"五言绝句","c":["作糜活饿夫，分食及龟鱼。","林深幽磬晚，犹想定回初。"]},{"t":"天冠山题咏二十二首 其三 炼丹井","f":"五言绝句","c":["丹成神仙去，井冽寒泉食。","甘美无比伦，华池咽玉液。"]},{"t":"天冠山题咏二十二首 其六 升仙台","f":"五言绝句","c":["仙台高几许，时时覆云气。","一去三千年，令人每翘企。"]},{"t":"天冠山题咏二十二首 其七 逍遥岩","f":"五言绝句","c":["兹岭可逍遥，下可坐百人。","岂徒木石居，真与猿鹤邻。"]},{"t":"天冠山题咏二十二首 其八 灵湫","f":"五言绝句","c":["灵湫不受污，深浅何足计。","小憩松竹鸣，萧萧山雨至。"]},{"t":"天冠山题咏二十二首 其十一 长生池","f":"五言绝句","c":["竹实凤将至，水清鱼自行。","着我草亭里，危坐学长生。"]},{"t":"天冠山题咏二十二首 其十二 道人岩","f":"五言绝句","c":["道士本避世，问之无姓字。","如何千载后，石室有人至。"]},{"t":"天冠山题咏二十二首 其十三 雷公岩","f":"五言绝句","c":["雷公起卧龙，为国作霖雨。","飞电掣金蛇，其谁敢余侮。"]},{"t":"天冠山题咏二十二首 其十四 石人峰","f":"五言绝句","c":["臣灵长亘天，何时化为石。","特立千万年，终古无人识。"]},{"t":"天冠山题咏二十二首 其十五 学堂岩","f":"五言绝句","c":["仙人非痴人，山中犹读书。","嗟我癈学久，闻此一长吁。"]},{"t":"天冠山题咏二十二首 其十六 老人峰","f":"五言绝句","c":["有石象老人，宛然如绘素。","稽首礼南极，苍苍在烟雾。"]},{"t":"天冠山题咏二十二首 其十七 月岩","f":"五言绝句","c":["月岩如偃月，风泉洒晴雪。","仙境在人间，真成两奇绝。"]},{"t":"天冠山题咏二十二首 其十八 凤山","f":"五言绝句","c":["山鸡爱羽毛，饮啄琪树间。","照影寒潭静，翔集落花闲。"]},{"t":"天冠山题咏二十二首 其十九 仙足岩","f":"五言绝句","c":["窈窕石屋间，中有仙人躅。","说与牧羊儿，慎勿伤吾足。"]},{"t":"天冠山题咏二十二首 其二十 鬼谷岩","f":"五言绝句","c":["鬼谷岩前石，唐文字字奇。","何当拂苍藓，细读老君碑。"]},{"t":"天冠山题咏二十二首 其二十一 风洞","f":"五言绝句","c":["石壁何空洞，中有风泠然。","安知列御寇，不向此中仙。"]},{"t":"天冠山题咏二十二首 其二十二 钓台","f":"五言绝句","c":["仙者非有求，坐石示投钓。","咄哉羊裘翁，同名不同调。"]},{"t":"玄洲十咏寄张贞居 其二 罗姑洞","f":"五言绝句","c":["翩翩十绝幡，飘飘九疑仙。","洞口薜萝长，来降是何年。"]},{"t":"题仲宾竹 其一","f":"五言绝句","c":["幽人夜不眠，月吐窗炯炯。","起寻管城公，奋髯写清影。"]},{"t":"题仲宾竹 其二","f":"五言绝句","c":["此君有高节，不与草木同。","萧萧三两竿，自足来清风。"]},{"t":"题周秀才此山堂 其二","f":"五言绝句","c":["爽气在襟袖，清风拂丝桐。","悠然适天趣，宴坐心融融。"]},{"t":"题孤山放鹤图 其二","f":"曲","c":["昔年曾到孤山，苍藤古木高寒。","想见先生风致，画图留与人看。"]},{"t":"初至都下即事 其一","f":"七言绝句","c":["海上春深柳色浓，蓬莱宫阙五云中。","半生落魄江湖上，今日钧天一梦同。"]},{"t":"浮玉山","f":"七言绝句","c":["玉湖流水清且闲，中有浮玉之名山。","千帆过尽莫天碧，惟见白云时往还。"]},{"t":"鄣南山中","f":"七言绝句","c":["山深草木自幽清，终日闻莺不见莺。","好作束书归隐计，蹇驴来往听泉声。"]},{"t":"奉和本斋先生午日绝句二首 其一","f":"七言绝句","c":["风雨凄凄五月寒，绿阴门巷思萧然。","客来载酒非问字，知是先生草太玄。"]},{"t":"奉和本斋先生午日绝句二首 其二","f":"七言绝句","c":["节序匆匆听自过，榴花能舞鸟能歌。","北窗高卧一杯酒，奈得渊明醉后何。"]},{"t":"酬罗伯寿 其二","f":"七言绝句","c":["㩀鞍北走燕山雪，策杖南游故国春。","万里归来头未白，他年句法更深醇。"]},{"t":"题苍林叠岫图 其一","f":"七言绝句","c":["桑苧未成鸿渐隐，丹青聊作虎头痴。","久知图画非儿戏，到处云山是我师。"]},{"t":"题苍林叠岫图 其二","f":"七言绝句","c":["溪上先人之敝庐，南山秀色照庭除。","何时共买扁舟去，看钓寒波缩项鱼。"]},{"t":"送王子庆诏檄浙东收郡县图籍 其二","f":"七言绝句","c":["安道幽居寄剡源，蓬蒿蔚蔚长丘园。","向来乘兴相寻意，何事空回不到门。"]},{"t":"送王子庆诏檄浙东收郡县图籍 其三","f":"七言绝句","c":["爱古探奇亦可怜，锦囊玉轴不论钱。","拟须跂马江头路，日日望君书画船。"]},{"t":"九月八日雨中闷坐和荅仇仁父张季野","f":"七言绝句","c":["容居破屋苦秋雨，黑潦侵阶灶欲沉。","青蕊明朝不堪摘，谁能载酒慰幽心。"]},{"t":"以画寄高仁卿","f":"七言绝句","c":["碧山清晓护晴岚，绿树经秋醉色酣。","谁是丹青三昧手，为君满意画江南。"]},{"t":"题秋胡戏妻图","f":"七言绝句","c":["相逢桑下说黄金，料得秋胡用计深。","不是别来浑未识，黄金聊试别来心。"]},{"t":"怀德清别业 其二","f":"七言绝句","c":["谷口春残黄鸟稀，辛夷花落杏花飞。","始怜幽竹山窗下，不改清阴待我归。"]},{"t":"过严陵钓台 其一","f":"七言绝句","c":["富春山中有客星，辞荣归来意更真。","羊裘坐钓沧波上，却笑刘郎非故人。"]},{"t":"过严陵钓台 其二","f":"七言绝句","c":["桐江水色映青山，安稳行人挂布帆。","回首风沙鞍马里，不知此地是尘凡。"]},{"t":"送山东廉访照磨于思容","f":"七言绝句","c":["林梢春动紫烟生，匹马东风十日程。","若到济南行乐处，城西泉上最关情。"]},{"t":"喜晴","f":"七言绝句","c":["久雨厌厌愁杀人，晚晴犹得见青春。","急须走马西湖路，杨柳淡黄如麴尘。"]},{"t":"简王搏霄乞芙蓉杏","f":"七言绝句","c":["杏花枝上红千叶，偏得春饶恼杀人。","早与折来供一醉，东风如此恐成尘。"]},{"t":"和韩君美二绝句 其一 金山","f":"七言绝句","c":["江水西来接太空，中流突兀涌鳌宫。","妙高台上一回首，看尽世途风浪中。"]},{"t":"和韩君美二绝句 其二 苏州","f":"七言绝句","c":["子胥死后巳无臣，中国由来渐属秦。","天下固知多美妇，五湖元自有高人。"]},{"t":"题所画梅竹赠石民瞻 其二","f":"七言绝句","c":["江南翠竹动成林，谁折寒枝寄赏音。","说与双清堂上客，萧然应见此君心。"]},{"t":"题所画梅竹幽兰水仙赠鹤皋 其一","f":"七言绝句","c":["千树瑶芳压水湄，西湖风月鬓成丝。","江南春色今何似，赖有高人把一枝。"]},{"t":"题所画梅竹幽兰水仙赠鹤皋 其二","f":"七言绝句","c":["萧䔥叶带雨声寒，袅袅枝摇月影残。","欲引九苞威凤宿，晴窗试写翠琅玕。"]},{"t":"题所画梅竹幽兰水仙赠鹤皋 其三","f":"七言绝句","c":["百草千花日夜新，此君林下始知春。","虽无令色如娇女，自有幽香似德人。"]},{"t":"题所画梅竹幽兰水仙赠鹤皋 其四","f":"七言绝句","c":["翠袖盈盈不受扶，天风缥缈降麻姑。","便应从此东吴去，几见蓬莱弱水枯。"]},{"t":"和黄景杜雪中即事 其一","f":"七言绝句","c":["燕雪常飞十月前，弊裘破帽过年年。","拥炉自笑何为者，欲买浊醪无一钱。"]},{"t":"送黄景杜","f":"七言绝句","c":["天下无双黄印曹，割鸡聊复试牛刀。","梅花香里听衙罢，明月泉边饮浊醪。"]},{"t":"偶成绝句二首奉怀宋齐彦学士田师孟省郎 其一","f":"七言绝句","c":["道山仙府旧曾居，堕在尘埃意不舒。","回首故人天上住，如何不寄半行书。"]},{"t":"偶成绝句二首奉怀宋齐彦学士田师孟省郎 其二","f":"七言绝句","c":["乍可望尘迎使者，何堪㩀案箠疲民。","济南虽有如渑酒，准拟愁中过一春。"]},{"t":"湖上莫归 其二","f":"七言绝句","c":["明时官府初无事，下走非才自觉忙。","奔走尘埃竟何补，故园松菊久应荒。"]},{"t":"春日漫兴","f":"七言绝句","c":["春事匆匆转眼过，满城流水绿阴多。","西园总有红千叶，尘土埋头奈尔河。"]},{"t":"题朱锐雪景","f":"七言绝句","c":["尘埃困人恒作恶，开卷惊看雪满楼。","安得眼前有此屋，仍呼陶谢与同游。"]},{"t":"即事三绝 其三","f":"七言绝句","c":["绕屋扶疏竹树清，飞飞燕雀共生成。","贫家自笑无金弹，数树枇杷总不生。"]},{"t":"又","f":"七言绝句","c":["草长前庭不用锄，自然生意满吾庐。","何须直待生书带，始信康成解著书。"]},{"t":"牧牛图","f":"七言绝句","c":["杨柳青青柳絮飞，陂塘草绿水生肥。","十犁耕罢朝来雨，却背斜阳自在归。"]},{"t":"题山水卷","f":"七言绝句","c":["霜后疏林叶尽乾，雨馀流水玉声寒。","世间多少闲庭榭，要向溪山好处安。"]},{"t":"题群仙壁","f":"七言绝句","c":["群仙来会蕊珠宫，花满琼山翠满空。","环佩珊珊五云际，半天鸾鹤舞春风。"]},{"t":"宫中口号 其二","f":"七言绝句","c":["殿西小殿号嘉禧，玉座中央静不移。","读罢经书香一炷，太平天子政无为。"]},{"t":"自警","f":"七言绝句","c":["齿豁头童六十三，一生事事总堪惭。","唯馀笔砚情犹在，留与人间作笑谈。"]},{"t":"刘时济归来堂","f":"七言绝句","c":["出处由来各有宜，他人何与强吟诗。","千年只有陶彭泽，解印归来更不疑。"]},{"t":"宿五华山怀德清别业","f":"七言绝句","c":["一夜松涛枕上鸣，五华山馆梦频惊。","何当归去芝亭上，坐听□翁韵玉笙。"]},{"t":"留题惠山","f":"七言绝句","c":["南朝古寺惠山前，裹茗来寻第二泉。","贪恋君恩当北去，野花啼鸟漫留连。"]},{"t":"徐敏父龙虎山仙岩闻鸡鸣寄玄卿 其一","f":"七言绝句","c":["天鸡三叫白云中，知有仙家住半空。","尘土恍然惊梦觉，碧桃花落自春风。"]},{"t":"徐敏父龙虎山仙岩闻鸡鸣寄玄卿 其二","f":"七言绝句","c":["泛泛轻舟溯碧溪，苍厓万仞有鸣鸡。","可惜吾侬不同往，便当着屐上丹梯。"]},{"t":"题苕溪绝句","f":"七言绝句","c":["自有天地有此溪，泓渟百折净无泥。","我居溪上尘不到，只疑家在青玻瓈。"]},{"t":"题四画 其一 桃源","f":"七言绝句","c":["桃源一去绝埃尘，无复渔郎再问津。","想得耕田并凿井，依然淳朴太平民。"]},{"t":"题四画 其二 渊明","f":"七言绝句","c":["渊明为令本非情，解印归来去就轻。","稚子迎门松菊在，半壶浊酒慰平生。"]},{"t":"题四画 其四 赤壁","f":"七言绝句","c":["周郎赤壁走曹公，万里江流斗两雄。","苏子赋成奇伟甚，长教人想谪仙风。"]},{"t":"偶得灵壁石笔格状如俗所谓钻云螭虎者因成绝句","f":"七言绝句","c":["玄螭穿透白云层，老眼平生见未曾。","开辟以来神物出，人间剞劂竟何能。"]},{"t":"题高彦敬画二轴 其一","f":"曲","c":["疏疏澹澹竹林间，烟雨冥?见远山。","记得西湖新霁后，与公携杖听潺湲。"]},{"t":"题高彦敬画二轴 其二","f":"七言绝句","c":["万木纷然摇落后，唯馀碧色见松林。","尚书雅有冰霜操，笔底时时寄此心。"]},{"t":"偶成 其二","f":"七言绝句","c":["末利花开小玉莲，香风引谒洞中仙。","梦回不记相逢语，明月清圆在枕边。"]},{"t":"即事 其二","f":"七言绝句","c":["橘子花香满四邻，绿阴如染净无尘。","幽斋独坐鸟声乐，万虑不干心地春。"]},{"t":"赠彭师立 其一","f":"七言绝句","c":["学书工拙何足计，名世不难传后难。","当有深知书法者，未容俗子议其间。"]},{"t":"赠彭师立 其二","f":"七言绝句","c":["古来名刻世可数，馀者未精心不降。","欲使清风传万古，须如明月印千江。"]}]};